window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id": "yy-18421", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "这些年，改革红利持续显现，市场活力不断，老党员信心更足。", "options": ["迸发", "暴发", "爆发", "突发"], "answer": 0, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选A。"}, {"id": "yy-18422", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "今年以来，城乡公共服务仍有落差，科研人员以实策逐步______差距。", "options": ["减小", "缩减", "缩小", "减少"], "answer": 2, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。"}, {"id": "yy-18423", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，让公共服务覆盖城乡，农技人员持续______政策体系。", "options": ["补完", "完缮", "完善", "修完"], "answer": 2, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。"}, {"id": "yy-18424", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "眼下，内生动力从哪里来？博物馆讲解员把功夫下在创新上。", "options": ["增强", "加强", "增添", "增大"], "answer": 0, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选A。"}, {"id": "yy-18425", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "这些年，发展为了人民，工程师把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增添", "增加", "增殖", "增进"], "answer": 3, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。"}, {"id": "yy-18426", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，老旧小区加装电梯、增设车位，乡村医生尽力______居民多样需求。", "options": ["充足", "充盈", "满意", "满足"], "answer": 3, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。"}, {"id": "yy-18427", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，初心如磐，使命在肩，程序员把承诺落到一件件小事上。", "options": ["践行", "旅行", "执行", "履行"], "answer": 0, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。"}, {"id": "yy-18428", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，在广袤乡野间，铁路养护工用汗水______出乡村振兴的崭新篇章。", "options": ["书写", "誊写", "描红", "抄写"], "answer": 0, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选A。"}, {"id": "yy-18429", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，危难时刻冲得上去，广大建设者的行动______了共产党员的担当。", "options": ["暴露", "彰显", "显露", "显摆"], "answer": 1, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。"}, {"id": "yy-18430", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "连日来，每个孩子都有闪光点，手工艺人善于______学生潜能。", "options": ["掘取", "开采", "挖出", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18431", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，邻里纠纷无小事，铁路养护工用真心______一件件矛盾。", "options": ["解开", "消融", "瓦解", "化解"], "answer": 3, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。"}, {"id": "yy-18432", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，每一起案件都关乎群众对法治的信仰，医护人员用公正裁判______正义。", "options": ["护卫", "保卫", "防御", "捍卫"], "answer": 3, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。"}, {"id": "yy-18433", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "今年以来，一网通办让数据多跑路，老党员以流程再造______政务效能。", "options": ["抬高", "拔高", "提高", "提升"], "answer": 3, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选D。"}, {"id": "yy-18434", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，两岸同胞亲情割不断，基层干部为青年交流______心灵心桥。", "options": ["修筑", "架起", "铺设", "垒砌"], "answer": 1, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。"}, {"id": "yy-18435", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["铲平", "破除", "捣毁", "拆除"], "answer": 1, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选B。"}, {"id": "yy-18436", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，停车难是城市治理的老大难，市场监管部门用共享思维______了这一难题。", "options": ["解释", "破解", "解冻", "解开"], "answer": 1, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选B。"}, {"id": "yy-18437", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，手握核心技术专利，志愿者们创新的底气。", "options": ["更强", "更足", "更硬", "更壮"], "answer": 1, "explanation": "「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。"}, {"id": "yy-18438", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "这些年，让农产品出村进城，网格员多方合力______销售通道。", "options": ["扩宽", "开辟", "开宽", "拓宽"], "answer": 3, "explanation": "「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选D。"}, {"id": "yy-18439", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "连日来，数据孤岛必须连起来，消防员下决心______部门间的壁垒。", "options": ["击碎", "砸破", "打碎", "打破"], "answer": 3, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。"}, {"id": "yy-18440", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，众人的事情由众人商量，农技人员把各方______到规划图上。", "options": ["聚拢", "归拢", "收拢", "凝聚"], "answer": 3, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选D。"}, {"id": "yy-18441", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，面对转型路上的重重难关，基层干部迎难而上，把一个个难关逐一______。", "options": ["克服", "化解", "破除", "攻克"], "answer": 3, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。"}, {"id": "yy-18442", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "近期，把风险挺在前面，农技人员织密织牢安全网。", "options": ["防守", "防备", "防范", "提防"], "answer": 2, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选C。"}, {"id": "yy-18443", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "岁末年初，筑起生态安全屏障，手工艺人让青山常在绿水长流。", "options": ["砌牢", "锁牢", "拴牢", "筑牢"], "answer": 3, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选D。"}, {"id": "yy-18444", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "一段时间以来，数据孤岛必须连起来，工程师下决心______部门间的壁垒。", "options": ["打破", "打碎", "击碎", "砸破"], "answer": 0, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。"}, {"id": "yy-18445", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，景区客流高峰来临，公交司机全员上岗______游览秩序。", "options": ["护卫", "保护", "维持", "维护"], "answer": 3, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选D。"}, {"id": "yy-18446", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，手握核心技术专利，手工艺人创新的底气。", "options": ["更强", "更足", "更壮", "更硬"], "answer": 1, "explanation": "「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。"}, {"id": "yy-18447", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "开春以来，纪律规矩挺在前面，快递员始终______纪律底线。", "options": ["严守", "遵守", "把守", "看守"], "answer": 0, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选A。"}, {"id": "yy-18448", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，安全底线不可逾越，乡村医生24小时轮班值守。", "options": ["镇守", "把守", "坚守", "看守"], "answer": 2, "explanation": "「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选C。"}, {"id": "yy-18449", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，营商环境就是生产力，基层干部让企业成长有沃土。", "options": ["培养", "厚植", "培育", "培植"], "answer": 1, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选B。"}, {"id": "yy-18450", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，停车难是城市治理的老大难，社区规划师用共享思维______了这一难题。", "options": ["破解", "解开", "解释", "解冻"], "answer": 0, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选A。"}, {"id": "yy-18451", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "近年来，一二三产融合发展，科研人员推动产业链不断延伸。", "options": ["延长", "延伸", "拉长", "伸长"], "answer": 1, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选B。"}, {"id": "yy-18452", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，市场细胞活跃起来，程序员让经济肌体活力。", "options": ["塞满", "充满", "填满", "装满"], "answer": 1, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。"}, {"id": "yy-18453", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "开春以来，数据孤岛必须连起来，广大建设者下决心______部门间的壁垒。", "options": ["砸破", "打碎", "击碎", "打破"], "answer": 3, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。"}, {"id": "yy-18454", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "盛夏时节，订单排到明年，工程师发展的信心。", "options": ["加倍", "倍增", "倍加", "倍受"], "answer": 1, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选B。"}, {"id": "yy-18455", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，靠山吃山靠水吃水，治沙工人因地制宜______资源优势。", "options": ["施展", "发展", "发挥", "发扬"], "answer": 2, "explanation": "「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选C。"}, {"id": "yy-18456", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "盛夏时节，景区客流高峰来临，执法人员全员上岗______游览秩序。", "options": ["护卫", "维护", "保护", "维持"], "answer": 1, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。"}, {"id": "yy-18457", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，每一起案件都关乎群众对法治的信仰，乡村医生用公正裁判______正义。", "options": ["捍卫", "护卫", "保卫", "防御"], "answer": 0, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选A。"}, {"id": "yy-18458", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "开春以来，危难时刻冲得上去，青年学子的行动______了共产党员的担当。", "options": ["暴露", "彰显", "显露", "显摆"], "answer": 1, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。"}, {"id": "yy-18459", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "今年以来，春潮拍岸千帆竞，环卫工人感受到创新活力。", "options": ["流出", "涌出", "淌动", "涌动"], "answer": 3, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选D。"}, {"id": "yy-18460", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，订单排到明年，市场监管部门发展的信心。", "options": ["倍受", "加倍", "倍增", "倍加"], "answer": 2, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。"}, {"id": "yy-18461", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "初秋时节，越是爬坡过坎，越要______必胜信心，税务干部一步一个脚印向前走。", "options": ["坚强", "坚定", "坚持不懈", "坚决"], "answer": 1, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。"}, {"id": "yy-18462", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，春潮拍岸千帆竞，广大建设者感受到创新活力。", "options": ["涌出", "涌动", "淌动", "流出"], "answer": 1, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选B。"}, {"id": "yy-18463", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "连日来，安全底线不可逾越，社区工作者24小时轮班值守。", "options": ["把守", "镇守", "看守", "坚守"], "answer": 3, "explanation": "「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选D。"}, {"id": "yy-18464", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "近期，老旧小区加装电梯、增设车位，环卫工人尽力______居民多样需求。", "options": ["充盈", "满足", "充足", "满意"], "answer": 1, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选B。"}, {"id": "yy-18465", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "连日来，被动状态必须改变，网格员用硬措施______了不利局面。", "options": ["倒转", "扭转", "反转", "回转"], "answer": 1, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选B。"}, {"id": "yy-18466", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，把消费潜力转化为增长实绩，审计人员拿出了实招硬招。", "options": ["发泄", "散发", "释放", "喷发"], "answer": 2, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选C。"}, {"id": "yy-18467", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，初心如磐，使命在肩，手工艺人把承诺落到一件件小事上。", "options": ["旅行", "履行", "执行", "践行"], "answer": 3, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选D。"}, {"id": "yy-18468", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "入冬以来，把监督防线扎到最基层，农技人员走村入户听民声。", "options": ["织密", "缝密", "织厚", "织补"], "answer": 0, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选A。"}, {"id": "yy-18469", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，每个孩子都有闪光点，民警善于______学生潜能。", "options": ["开采", "挖出", "掘取", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18470", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，产业发展的根基越牢，抗风险的能力就越强，护林员深谙此理，先把根基打扎实。", "options": ["夯实", "铺设", "垒砌", "敲打"], "answer": 0, "explanation": "「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选A。"}, {"id": "yy-18471", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，订单排到明年，图书管理员发展的信心。", "options": ["倍增", "加倍", "倍加", "倍受"], "answer": 0, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选A。"}, {"id": "yy-18472", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，市场细胞活跃起来，青年学子让经济肌体活力。", "options": ["充满", "塞满", "填满", "装满"], "answer": 0, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选A。"}, {"id": "yy-18473", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，把风险挺在前面，治沙工人织密织牢安全网。", "options": ["防范", "防备", "防守", "提防"], "answer": 0, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选A。"}, {"id": "yy-18474", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "一段时间以来，筑起生态安全屏障，茶农让青山常在绿水长流。", "options": ["锁牢", "拴牢", "砌牢", "筑牢"], "answer": 3, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选D。"}, {"id": "yy-18475", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，一次次说到做到，文旅部门用行动______了群众的信任。", "options": ["获得", "换取", "博得", "赢得"], "answer": 3, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。"}, {"id": "yy-18476", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近年来，传统村落保护性开发，铁路养护工既富了口袋，也______了乡愁。", "options": ["留住", "拘留", "扣留", "截留"], "answer": 0, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。"}, {"id": "yy-18477", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近期，把风险挺在前面，博物馆讲解员织密织牢安全网。", "options": ["防备", "防范", "提防", "防守"], "answer": 1, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选B。"}, {"id": "yy-18478", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "岁末年初，城乡公共服务仍有落差，科研人员以实策逐步______差距。", "options": ["减小", "减少", "缩小", "缩减"], "answer": 2, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。"}, {"id": "yy-18479", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，夜市灯火点亮街巷，护林员为城市______了烟火活力。", "options": ["增补", "增加", "追加", "增添"], "answer": 3, "explanation": "「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选D。"}, {"id": "yy-18480", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，汛期将至，工程师对辖区地质灾害隐患逐点______。", "options": ["检察", "排查", "检查", "普查"], "answer": 1, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。"}, {"id": "yy-18481", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "入冬以来，在广袤乡野间，青年学子用汗水______出乡村振兴的崭新篇章。", "options": ["抄写", "书写", "描红", "誊写"], "answer": 1, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选B。"}, {"id": "yy-18482", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，把资源优势变成产业优势，治沙工人下大气力______区域品牌。", "options": ["打造", "拍打", "锻打", "打制"], "answer": 0, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选A。"}, {"id": "yy-18483", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "开春以来，老工业基地涅槃重生，程序员加快新旧动能步伐。", "options": ["改换", "变换", "转变", "转换"], "answer": 3, "explanation": "「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选D。"}, {"id": "yy-18484", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "入冬以来，老旧小区加装电梯、增设车位，农技人员尽力______居民多样需求。", "options": ["充盈", "满意", "满足", "充足"], "answer": 2, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选C。"}, {"id": "yy-18485", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "连日来，发展为了人民，护林员把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增加", "增进", "增添", "增殖"], "answer": 1, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选B。"}, {"id": "yy-18486", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "连日来，民生领域还有欠账，市场监管部门列出清单逐项______短板。", "options": ["贴补", "补齐", "补丁", "修补"], "answer": 1, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。"}, {"id": "yy-18487", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，数据孤岛必须连起来，乡村医生下决心______部门间的壁垒。", "options": ["击碎", "打碎", "砸破", "打破"], "answer": 3, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。"}, {"id": "yy-18488", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "入冬以来，改革到了深水区，文旅部门以钉钉子精神______工作局面。", "options": ["打开", "揭开", "掀开", "翻开"], "answer": 0, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。"}, {"id": "yy-18489", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近期，面对转型路上的重重难关，青年学子迎难而上，把一个个难关逐一______。", "options": ["化解", "攻克", "克服", "破除"], "answer": 1, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选B。"}, {"id": "yy-18490", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "初秋时节，脱贫不是终点，网格员多措并举______脱贫成果。", "options": ["凝固", "加固", "巩固", "稳固"], "answer": 2, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选C。"}, {"id": "yy-18491", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，传统村落保护性开发，快递员既富了口袋，也______了乡愁。", "options": ["截留", "拘留", "留住", "扣留"], "answer": 2, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选C。"}, {"id": "yy-18492", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，一次次说到做到，社区工作者用行动______了群众的信任。", "options": ["赢得", "获得", "换取", "博得"], "answer": 0, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选A。"}, {"id": "yy-18493", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "开春以来，初心如磐，使命在肩，法官把承诺落到一件件小事上。", "options": ["执行", "旅行", "践行", "履行"], "answer": 2, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。"}, {"id": "yy-18494", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "这些年，纪律规矩挺在前面，设计师始终______纪律底线。", "options": ["严守", "看守", "遵守", "把守"], "answer": 0, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选A。"}, {"id": "yy-18495", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "入冬以来，把风险挺在前面，农技人员织密织牢安全网。", "options": ["防备", "提防", "防范", "防守"], "answer": 2, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选C。"}, {"id": "yy-18496", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "眼下，一网通办让数据多跑路，基层干部以流程再造______政务效能。", "options": ["抬高", "提高", "提升", "拔高"], "answer": 2, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选C。"}, {"id": "yy-18497", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，古城修缮不搞大拆大建，程序员让千年文脉在街巷间静静流淌。", "options": ["接通", "延续", "连接", "续接"], "answer": 1, "explanation": "「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选B。"}, {"id": "yy-18498", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "一段时间以来，小哨兵大作用，网格员让基层网格______更大作用。", "options": ["发扬", "表现", "发挥", "施展"], "answer": 2, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选C。"}, {"id": "yy-18499", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，越是爬坡过坎，越要______必胜信心，公交司机一步一个脚印向前走。", "options": ["坚持不懈", "坚决", "坚定", "坚强"], "answer": 2, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选C。"}, {"id": "yy-18500", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "开春以来，初心如磐，使命在肩，社区规划师把承诺落到一件件小事上。", "options": ["践行", "旅行", "执行", "履行"], "answer": 0, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。"}, {"id": "yy-18501", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "一段时间以来，一年一度的民生大考结束，渔民向群众______了温暖的答卷。", "options": ["交出", "上缴", "递交", "呈报"], "answer": 0, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选A。"}, {"id": "yy-18502", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，订单排到明年，图书管理员发展的信心。", "options": ["倍受", "倍加", "倍增", "加倍"], "answer": 2, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。"}, {"id": "yy-18503", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，一年一度的民生大考结束，执法人员向群众______了温暖的答卷。", "options": ["递交", "交出", "呈报", "上缴"], "answer": 1, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。"}, {"id": "yy-18504", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，乡情是最深的牵挂，青年学子以商会为平台______情感纽带。", "options": ["织牢", "系牢", "捆牢", "绑牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18505", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，把资源优势变成产业优势，治沙工人下大气力______区域品牌。", "options": ["锻打", "打制", "打造", "拍打"], "answer": 2, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选C。"}, {"id": "yy-18506", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，几十年如一日，非遗传承人在平凡岗位上______着为民初心。", "options": ["守卫", "把守", "保守", "坚守"], "answer": 3, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。"}, {"id": "yy-18507", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，一网通办让数据多跑路，铁路养护工以流程再造______政务效能。", "options": ["提升", "拔高", "抬高", "提高"], "answer": 0, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选A。"}, {"id": "yy-18508", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，誓师大会上，手工艺人精神斗志，誓言响彻训练场。", "options": ["昂扬", "高扬", "高涨", "高昂"], "answer": 0, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选A。"}, {"id": "yy-18509", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "眼下，急难险重任务面前，驻村干部主动______最重的责任。", "options": ["背起", "扛起", "抬起", "挑起"], "answer": 1, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选B。"}, {"id": "yy-18510", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，内生动力从哪里来？民警把功夫下在创新上。", "options": ["加强", "增添", "增大", "增强"], "answer": 3, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选D。"}, {"id": "yy-18511", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，卡脖子技术亟待攻坚，市场监管部门集中力量______一个个瓶颈。", "options": ["撞破", "突破", "冲破", "捅破"], "answer": 1, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选B。"}, {"id": "yy-18512", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，订单排到明年，护林员发展的信心。", "options": ["加倍", "倍加", "倍增", "倍受"], "answer": 2, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选C。"}, {"id": "yy-18513", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "入冬以来，从受理到反馈全流程留痕，农技人员以数字化手段______管理闭环。", "options": ["搭圈", "构画", "构建", "圈画"], "answer": 2, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选C。"}, {"id": "yy-18514", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "入冬以来，二十年只做一件事，消防员在细分领域里做到极致。", "options": ["深钻", "深掘", "深挖", "深耕"], "answer": 3, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选D。"}, {"id": "yy-18515", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，内生动力从哪里来？基层干部把功夫下在创新上。", "options": ["增大", "加强", "增强", "增添"], "answer": 2, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选C。"}, {"id": "yy-18516", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "连日来，老工业基地涅槃重生，设计师加快新旧动能步伐。", "options": ["改换", "转变", "变换", "转换"], "answer": 3, "explanation": "「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选D。"}, {"id": "yy-18517", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，几十年如一日，乡村医生在平凡岗位上______着为民初心。", "options": ["保守", "守卫", "把守", "坚守"], "answer": 3, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。"}, {"id": "yy-18518", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，面对转型路上的重重难关，博物馆讲解员迎难而上，把一个个难关逐一______。", "options": ["克服", "破除", "化解", "攻克"], "answer": 3, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。"}, {"id": "yy-18519", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "初秋时节，卡脖子技术亟待攻坚，科研人员集中力量______一个个瓶颈。", "options": ["撞破", "冲破", "捅破", "突破"], "answer": 3, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。"}, {"id": "yy-18520", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "一段时间以来，红色资源是最生动的教材，基层干部让红色血脉代代相传。", "options": ["赓续", "延续", "继续", "接续"], "answer": 0, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选A。"}, {"id": "yy-18521", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，一次次说到做到，法官用行动______了群众的信任。", "options": ["换取", "赢得", "获得", "博得"], "answer": 1, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选B。"}, {"id": "yy-18522", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，一年一度的民生大考结束，志愿者们向群众______了温暖的答卷。", "options": ["交出", "上缴", "呈报", "递交"], "answer": 0, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选A。"}, {"id": "yy-18523", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "连日来，汛期将至，调解员对辖区地质灾害隐患逐点______。", "options": ["排查", "普查", "检查", "检察"], "answer": 0, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选A。"}, {"id": "yy-18524", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "盛夏时节，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["拆除", "铲平", "捣毁", "破除"], "answer": 3, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选D。"}, {"id": "yy-18525", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，每一起案件都关乎群众对法治的信仰，铁路养护工用公正裁判______正义。", "options": ["防御", "保卫", "护卫", "捍卫"], "answer": 3, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。"}, {"id": "yy-18526", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，被动状态必须改变，电力工人用硬措施______了不利局面。", "options": ["倒转", "反转", "回转", "扭转"], "answer": 3, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。"}, {"id": "yy-18527", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "一段时间以来，老艺人收徒授艺，让千年技艺薪火。", "options": ["递送", "传递", "互传", "相传"], "answer": 3, "explanation": "「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选D。"}, {"id": "yy-18528", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "眼下，一二三产融合发展，文旅部门推动产业链不断延伸。", "options": ["拉长", "延伸", "伸长", "延长"], "answer": 1, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选B。"}, {"id": "yy-18529", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，跳出一时一地看发展，农技人员着力______开放共赢的新格局。", "options": ["架造", "构建", "构作", "搭造"], "answer": 1, "explanation": "「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选B。"}, {"id": "yy-18530", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "入冬以来，急难险重任务面前，志愿者们主动______最重的责任。", "options": ["挑起", "背起", "抬起", "扛起"], "answer": 3, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。"}, {"id": "yy-18531", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "盛夏时节，一二三产融合发展，博物馆讲解员推动产业链不断延伸。", "options": ["延长", "伸长", "延伸", "拉长"], "answer": 2, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选C。"}, {"id": "yy-18532", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "一段时间以来，城乡公共服务仍有落差，驻村干部以实策逐步______差距。", "options": ["减小", "减少", "缩减", "缩小"], "answer": 3, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。"}, {"id": "yy-18533", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，每个孩子都有闪光点，博物馆讲解员善于______学生潜能。", "options": ["挖掘", "掘取", "开采", "挖出"], "answer": 0, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选A。"}, {"id": "yy-18534", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "连日来，把资源优势变成产业优势，社区规划师下大气力______区域品牌。", "options": ["拍打", "打制", "锻打", "打造"], "answer": 3, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选D。"}, {"id": "yy-18535", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "一段时间以来，靠山吃山靠水吃水，驻村干部因地制宜______资源优势。", "options": ["发扬", "发挥", "施展", "发展"], "answer": 1, "explanation": "「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选B。"}, {"id": "yy-18536", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "开春以来，让新业态释放新动能，乡村医生在制度创新上先行先试。", "options": ["发动", "点燃", "激发", "引爆"], "answer": 2, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选C。"}, {"id": "yy-18537", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "眼下，二十年只做一件事，民警在细分领域里做到极致。", "options": ["深钻", "深耕", "深挖", "深掘"], "answer": 1, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选B。"}, {"id": "yy-18538", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "开春以来，在广袤乡野间，驻村干部用汗水______出乡村振兴的崭新篇章。", "options": ["描红", "书写", "誊写", "抄写"], "answer": 1, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选B。"}, {"id": "yy-18539", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "眼下，每一起案件都关乎群众对法治的信仰，法官用公正裁判______正义。", "options": ["防御", "捍卫", "保卫", "护卫"], "answer": 1, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。"}, {"id": "yy-18540", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，把消费潜力转化为增长实绩，果农拿出了实招硬招。", "options": ["释放", "散发", "发泄", "喷发"], "answer": 0, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。"}, {"id": "yy-18541", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "一段时间以来，邻里纠纷无小事，执法人员用真心______一件件矛盾。", "options": ["消融", "瓦解", "化解", "解开"], "answer": 2, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。"}, {"id": "yy-18542", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "开春以来，把监督防线扎到最基层，手工艺人走村入户听民声。", "options": ["织密", "缝密", "织补", "织厚"], "answer": 0, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选A。"}, {"id": "yy-18543", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "入冬以来，每一起案件都关乎群众对法治的信仰，医护人员用公正裁判______正义。", "options": ["保卫", "捍卫", "防御", "护卫"], "answer": 1, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。"}, {"id": "yy-18544", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "岁末年初，把家国情怀融入课堂，图书管理员用身边故事打动学生。", "options": ["培土", "施肥", "厚植", "浇灌"], "answer": 2, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选C。"}, {"id": "yy-18545", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "盛夏时节，政府、市场、社会同向发力，工程师让各方______成强大合力。", "options": ["汇集", "汇合", "汇聚", "聚合"], "answer": 2, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选C。"}, {"id": "yy-18546", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "入冬以来，一网通办让数据多跑路，茶农以流程再造______政务效能。", "options": ["拔高", "提高", "提升", "抬高"], "answer": 2, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选C。"}, {"id": "yy-18547", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "近年来，面对转型路上的重重难关，农技人员迎难而上，把一个个难关逐一______。", "options": ["克服", "化解", "破除", "攻克"], "answer": 3, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。"}, {"id": "yy-18548", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，在广袤乡野间，电力工人用汗水______出乡村振兴的崭新篇章。", "options": ["描红", "抄写", "书写", "誊写"], "answer": 2, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。"}, {"id": "yy-18549", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "这些年，春潮拍岸千帆竞，消防员感受到创新活力。", "options": ["涌动", "流出", "淌动", "涌出"], "answer": 0, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选A。"}, {"id": "yy-18550", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，初心如磐，使命在肩，社区工作者把承诺落到一件件小事上。", "options": ["旅行", "践行", "履行", "执行"], "answer": 1, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选B。"}, {"id": "yy-18551", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，誓师大会上，审计人员精神斗志，誓言响彻训练场。", "options": ["高涨", "高昂", "高扬", "昂扬"], "answer": 3, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。"}, {"id": "yy-18552", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，被动状态必须改变，审计人员用硬措施______了不利局面。", "options": ["扭转", "回转", "倒转", "反转"], "answer": 0, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选A。"}, {"id": "yy-18553", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "连日来，脱贫不是终点，志愿者们多措并举______脱贫成果。", "options": ["巩固", "稳固", "加固", "凝固"], "answer": 0, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。"}, {"id": "yy-18554", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "入冬以来，卡脖子技术亟待攻坚，基层干部集中力量______一个个瓶颈。", "options": ["突破", "冲破", "捅破", "撞破"], "answer": 0, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。"}, {"id": "yy-18555", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，急难险重任务面前，茶农主动______最重的责任。", "options": ["扛起", "挑起", "背起", "抬起"], "answer": 0, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选A。"}, {"id": "yy-18556", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，减税降费政策落地，志愿者们让企业真切感受到红利。", "options": ["发放", "发射", "释放", "散发"], "answer": 2, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选C。"}, {"id": "yy-18557", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "岁末年初，市场细胞活跃起来，农技人员让经济肌体活力。", "options": ["填满", "装满", "塞满", "充满"], "answer": 3, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选D。"}, {"id": "yy-18558", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["破除", "拆除", "捣毁", "铲平"], "answer": 0, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选A。"}, {"id": "yy-18559", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "连日来，金杯银杯不如老百姓的口碑，护林员把每件小事都当大事办。", "options": ["创立", "设立", "建立", "树立"], "answer": 3, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选D。"}, {"id": "yy-18560", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "开春以来，危难时刻冲得上去，社区规划师的行动______了共产党员的担当。", "options": ["显露", "显摆", "彰显", "暴露"], "answer": 2, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选C。"}, {"id": "yy-18561", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，两岸同胞亲情割不断，执法人员为青年交流______心灵心桥。", "options": ["垒砌", "铺设", "架起", "修筑"], "answer": 2, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。"}, {"id": "yy-18562", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "今年以来，两岸同胞亲情割不断，驻村干部为青年交流______心灵心桥。", "options": ["铺设", "架起", "修筑", "垒砌"], "answer": 1, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。"}, {"id": "yy-18563", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，放宽准入激发创业热情，公交司机让创造活力。", "options": ["涌流", "涌出", "淌出", "流出"], "answer": 0, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选A。"}, {"id": "yy-18564", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "连日来，面对转型路上的重重难关，程序员迎难而上，把一个个难关逐一______。", "options": ["化解", "克服", "攻克", "破除"], "answer": 2, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选C。"}, {"id": "yy-18565", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，发展为了人民，社区规划师把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增添", "增殖", "增进", "增加"], "answer": 2, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选C。"}, {"id": "yy-18566", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "连日来，新区建设的宏伟蓝图已经展开，医护人员正把一张张蓝图变成施工图。", "options": ["绘就", "修筑", "耕耘", "编织"], "answer": 0, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。"}, {"id": "yy-18567", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，发展为了人民，基层干部把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增进", "增加", "增殖", "增添"], "answer": 0, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选A。"}, {"id": "yy-18568", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，一揽子政策精准落地，环卫工人着力______市场信心。", "options": ["提起", "振作", "提振", "鼓动"], "answer": 2, "explanation": "「提振」与「信心」搭配得当。「提振信心」为固定搭配；「提起」多与精神、话题搭配；「振作」为不及物动词；「鼓动」含煽动义。故选C。"}, {"id": "yy-18569", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，市场不是法外之地，环卫工人以制度______交易秩序。", "options": ["规正", "规范", "规定", "规整"], "answer": 1, "explanation": "「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选B。"}, {"id": "yy-18570", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，安全底线不可逾越，审计人员24小时轮班值守。", "options": ["看守", "镇守", "把守", "坚守"], "answer": 3, "explanation": "「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选D。"}, {"id": "yy-18571", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，一次次说到做到，文旅部门用行动______了群众的信任。", "options": ["博得", "换取", "赢得", "获得"], "answer": 2, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。"}, {"id": "yy-18572", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，数据孤岛必须连起来，教师下决心______部门间的壁垒。", "options": ["砸破", "打破", "击碎", "打碎"], "answer": 1, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选B。"}, {"id": "yy-18573", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "一段时间以来，一网通办让数据多跑路，铁路养护工以流程再造______政务效能。", "options": ["抬高", "拔高", "提升", "提高"], "answer": 2, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选C。"}, {"id": "yy-18574", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "盛夏时节，绿水青山就是金山银山，老党员代代接力______绿色生态。", "options": ["守望", "守护", "守候", "看守"], "answer": 1, "explanation": "「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选B。"}, {"id": "yy-18575", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "初秋时节，市场不是法外之地，社区工作者以制度______交易秩序。", "options": ["规范", "规定", "规整", "规正"], "answer": 0, "explanation": "「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选A。"}, {"id": "yy-18576", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近年来，产业发展的根基越牢，抗风险的能力就越强，驻村干部深谙此理，先把根基打扎实。", "options": ["垒砌", "铺设", "敲打", "夯实"], "answer": 3, "explanation": "「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选D。"}, {"id": "yy-18577", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，乡情是最深的牵挂，法官以商会为平台______情感纽带。", "options": ["织牢", "捆牢", "系牢", "绑牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18578", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，每一起案件都关乎群众对法治的信仰，执法人员用公正裁判______正义。", "options": ["护卫", "捍卫", "保卫", "防御"], "answer": 1, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选B。"}, {"id": "yy-18579", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，把资源优势变成产业优势，果农下大气力______区域品牌。", "options": ["拍打", "打造", "打制", "锻打"], "answer": 1, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选B。"}, {"id": "yy-18580", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，民生实事清单公示上墙，乡村医生一件一件______承诺。", "options": ["达成", "实现", "兑现", "完成"], "answer": 2, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选C。"}, {"id": "yy-18581", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，一二三产融合发展，网格员推动产业链不断延伸。", "options": ["拉长", "伸长", "延伸", "延长"], "answer": 2, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选C。"}, {"id": "yy-18582", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["破除", "铲平", "拆除", "捣毁"], "answer": 0, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选A。"}, {"id": "yy-18583", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，一二三产融合发展，公交司机推动产业链不断延伸。", "options": ["伸长", "延长", "拉长", "延伸"], "answer": 3, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。"}, {"id": "yy-18584", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，两岸同胞亲情割不断，广大建设者为青年交流______心灵心桥。", "options": ["架起", "垒砌", "修筑", "铺设"], "answer": 0, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选A。"}, {"id": "yy-18585", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "岁末年初，老厂房变身文创园，治沙工人让工业遗存______新的活力。", "options": ["更新", "换发", "焕新", "焕发"], "answer": 3, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选D。"}, {"id": "yy-18586", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "入冬以来，小哨兵大作用，果农让基层网格______更大作用。", "options": ["发扬", "施展", "表现", "发挥"], "answer": 3, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选D。"}, {"id": "yy-18587", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "盛夏时节，每一起案件都关乎群众对法治的信仰，治沙工人用公正裁判______正义。", "options": ["防御", "保卫", "护卫", "捍卫"], "answer": 3, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。"}, {"id": "yy-18588", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "入冬以来，民生领域还有欠账，基层干部列出清单逐项______短板。", "options": ["补丁", "修补", "贴补", "补齐"], "answer": 3, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选D。"}, {"id": "yy-18589", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，几十年如一日，农技人员在平凡岗位上______着为民初心。", "options": ["把守", "守卫", "保守", "坚守"], "answer": 3, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。"}, {"id": "yy-18590", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "连日来，内生动力从哪里来？民警把功夫下在创新上。", "options": ["增强", "增添", "增大", "加强"], "answer": 0, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选A。"}, {"id": "yy-18591", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，初心如磐，使命在肩，市场监管部门把承诺落到一件件小事上。", "options": ["执行", "旅行", "履行", "践行"], "answer": 3, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选D。"}, {"id": "yy-18592", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，民生领域还有欠账，非遗传承人列出清单逐项______短板。", "options": ["补丁", "补齐", "贴补", "修补"], "answer": 1, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。"}, {"id": "yy-18593", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "眼下，汛期将至，护林员对辖区地质灾害隐患逐点______。", "options": ["检查", "排查", "普查", "检察"], "answer": 1, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。"}, {"id": "yy-18594", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "这些年，老工业基地涅槃重生，教师加快新旧动能步伐。", "options": ["改换", "转变", "变换", "转换"], "answer": 3, "explanation": "「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选D。"}, {"id": "yy-18595", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，让公共服务覆盖城乡，铁路养护工持续______政策体系。", "options": ["修完", "完善", "完缮", "补完"], "answer": 1, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选B。"}, {"id": "yy-18596", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近期，内生动力从哪里来？果农把功夫下在创新上。", "options": ["增添", "增强", "增大", "加强"], "answer": 1, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。"}, {"id": "yy-18597", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "入冬以来，停车难是城市治理的老大难，茶农用共享思维______了这一难题。", "options": ["解开", "解冻", "解释", "破解"], "answer": 3, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选D。"}, {"id": "yy-18598", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "连日来，纪律规矩挺在前面，渔民始终______纪律底线。", "options": ["把守", "看守", "遵守", "严守"], "answer": 3, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选D。"}, {"id": "yy-18599", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，汛期将至，环卫工人对辖区地质灾害隐患逐点______。", "options": ["检察", "检查", "排查", "普查"], "answer": 2, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选C。"}, {"id": "yy-18600", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "今年以来，一次次说到做到，渔民用行动______了群众的信任。", "options": ["博得", "赢得", "获得", "换取"], "answer": 1, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选B。"}, {"id": "yy-18601", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "初秋时节，红色资源是最生动的教材，农技人员让红色血脉代代相传。", "options": ["接续", "继续", "延续", "赓续"], "answer": 3, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选D。"}, {"id": "yy-18602", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "眼下，放宽准入激发创业热情，市场监管部门让创造活力。", "options": ["淌出", "涌出", "涌流", "流出"], "answer": 2, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。"}, {"id": "yy-18603", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，停车难是城市治理的老大难，志愿者们用共享思维______了这一难题。", "options": ["解释", "破解", "解开", "解冻"], "answer": 1, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选B。"}, {"id": "yy-18604", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "盛夏时节，放宽准入激发创业热情，医护人员让创造活力。", "options": ["淌出", "涌流", "流出", "涌出"], "answer": 1, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。"}, {"id": "yy-18605", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，市场细胞活跃起来，乡村医生让经济肌体活力。", "options": ["填满", "充满", "塞满", "装满"], "answer": 1, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。"}, {"id": "yy-18606", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "一段时间以来，每个孩子都有闪光点，青年学子善于______学生潜能。", "options": ["开采", "掘取", "挖出", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18607", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "初秋时节，每个孩子都有闪光点，法官善于______学生潜能。", "options": ["开采", "掘取", "挖出", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18608", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "入冬以来，放宽准入激发创业热情，果农让创造活力。", "options": ["淌出", "流出", "涌流", "涌出"], "answer": 2, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。"}, {"id": "yy-18609", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近年来，古城修缮不搞大拆大建，果农让千年文脉在街巷间静静流淌。", "options": ["接通", "延续", "连接", "续接"], "answer": 1, "explanation": "「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选B。"}, {"id": "yy-18610", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，老厂房变身文创园，公交司机让工业遗存______新的活力。", "options": ["焕发", "更新", "焕新", "换发"], "answer": 0, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。"}, {"id": "yy-18611", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，一年一度的民生大考结束，社区规划师向群众______了温暖的答卷。", "options": ["呈报", "上缴", "递交", "交出"], "answer": 3, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。"}, {"id": "yy-18612", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，手握核心技术专利，网格员创新的底气。", "options": ["更壮", "更足", "更强", "更硬"], "answer": 1, "explanation": "「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。"}, {"id": "yy-18613", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，订单排到明年，果农发展的信心。", "options": ["加倍", "倍增", "倍加", "倍受"], "answer": 1, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选B。"}, {"id": "yy-18614", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，金杯银杯不如老百姓的口碑，驻村干部把每件小事都当大事办。", "options": ["树立", "设立", "创立", "建立"], "answer": 0, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选A。"}, {"id": "yy-18615", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，在广袤乡野间，医护人员用汗水______出乡村振兴的崭新篇章。", "options": ["描红", "誊写", "书写", "抄写"], "answer": 2, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。"}, {"id": "yy-18616", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，数据孤岛必须连起来，护林员下决心______部门间的壁垒。", "options": ["砸破", "打碎", "打破", "击碎"], "answer": 2, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选C。"}, {"id": "yy-18617", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，让公共服务覆盖城乡，环卫工人持续______政策体系。", "options": ["完善", "补完", "完缮", "修完"], "answer": 0, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选A。"}, {"id": "yy-18618", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，邻里纠纷无小事，教师用真心______一件件矛盾。", "options": ["消融", "解开", "化解", "瓦解"], "answer": 2, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。"}, {"id": "yy-18619", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "一段时间以来，放宽准入激发创业热情，手工艺人让创造活力。", "options": ["流出", "涌流", "淌出", "涌出"], "answer": 1, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。"}, {"id": "yy-18620", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，红色资源是最生动的教材，设计师让红色血脉代代相传。", "options": ["赓续", "延续", "继续", "接续"], "answer": 0, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选A。"}, {"id": "yy-18621", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "今年以来，改革红利持续显现，市场活力不断，基层干部信心更足。", "options": ["突发", "爆发", "暴发", "迸发"], "answer": 3, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选D。"}, {"id": "yy-18622", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "眼下，卡脖子技术亟待攻坚，快递员集中力量______一个个瓶颈。", "options": ["撞破", "冲破", "突破", "捅破"], "answer": 2, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选C。"}, {"id": "yy-18623", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，夜市灯火点亮街巷，设计师为城市______了烟火活力。", "options": ["增加", "增添", "增补", "追加"], "answer": 1, "explanation": "「增添」与「活力」搭配得当。「增添活力」为惯用搭配；「增加」多与数量搭配；「追加」多与投资搭配；「增补」多与人员、内容搭配。故选B。"}, {"id": "yy-18624", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "近年来，城乡公共服务仍有落差，民警以实策逐步______差距。", "options": ["缩小", "减少", "缩减", "减小"], "answer": 0, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选A。"}, {"id": "yy-18625", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "初秋时节，民生领域还有欠账，审计人员列出清单逐项______短板。", "options": ["修补", "补齐", "补丁", "贴补"], "answer": 1, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。"}, {"id": "yy-18626", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "盛夏时节，乡情是最深的牵挂，农技人员以商会为平台______情感纽带。", "options": ["捆牢", "织牢", "绑牢", "系牢"], "answer": 1, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选B。"}, {"id": "yy-18627", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，邻里纠纷无小事，调解员用真心______一件件矛盾。", "options": ["消融", "解开", "瓦解", "化解"], "answer": 3, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。"}, {"id": "yy-18628", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，把监督防线扎到最基层，铁路养护工走村入户听民声。", "options": ["缝密", "织厚", "织补", "织密"], "answer": 3, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选D。"}, {"id": "yy-18629", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，把资源优势变成产业优势，设计师下大气力______区域品牌。", "options": ["打制", "拍打", "打造", "锻打"], "answer": 2, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选C。"}, {"id": "yy-18630", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，靠山吃山靠水吃水，环卫工人因地制宜______资源优势。", "options": ["发挥", "发扬", "发展", "施展"], "answer": 0, "explanation": "「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选A。"}, {"id": "yy-18631", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "连日来，两岸同胞亲情割不断，茶农为青年交流______心灵心桥。", "options": ["铺设", "垒砌", "修筑", "架起"], "answer": 3, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选D。"}, {"id": "yy-18632", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "岁末年初，春潮拍岸千帆竞，志愿者们感受到创新活力。", "options": ["涌出", "流出", "淌动", "涌动"], "answer": 3, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选D。"}, {"id": "yy-18633", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，一次次说到做到，治沙工人用行动______了群众的信任。", "options": ["博得", "换取", "赢得", "获得"], "answer": 2, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。"}, {"id": "yy-18634", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，民生实事清单公示上墙，调解员一件一件______承诺。", "options": ["实现", "达成", "完成", "兑现"], "answer": 3, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选D。"}, {"id": "yy-18635", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "连日来，两岸同胞亲情割不断，基层干部为青年交流______心灵心桥。", "options": ["架起", "铺设", "修筑", "垒砌"], "answer": 0, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选A。"}, {"id": "yy-18636", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，越是爬坡过坎，越要______必胜信心，公交司机一步一个脚印向前走。", "options": ["坚决", "坚定", "坚强", "坚持不懈"], "answer": 1, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。"}, {"id": "yy-18637", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "一段时间以来，一次次说到做到，法官用行动______了群众的信任。", "options": ["换取", "获得", "博得", "赢得"], "answer": 3, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选D。"}, {"id": "yy-18638", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "盛夏时节，万丈高楼平地起，电力工人一锤一钎______发展基础。", "options": ["砸实", "踩实", "夯实", "填实"], "answer": 2, "explanation": "「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选C。"}, {"id": "yy-18639", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "盛夏时节，春潮拍岸千帆竞，手工艺人感受到创新活力。", "options": ["涌动", "流出", "淌动", "涌出"], "answer": 0, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选A。"}, {"id": "yy-18640", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，让公共服务覆盖城乡，快递员持续______政策体系。", "options": ["完善", "补完", "完缮", "修完"], "answer": 0, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选A。"}, {"id": "yy-18641", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，初心如磐，使命在肩，电力工人把承诺落到一件件小事上。", "options": ["践行", "履行", "旅行", "执行"], "answer": 0, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。"}, {"id": "yy-18642", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，跳出一时一地看发展，渔民着力______开放共赢的新格局。", "options": ["构建", "构作", "搭造", "架造"], "answer": 0, "explanation": "「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选A。"}, {"id": "yy-18643", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "连日来，越是众声喧哗，越需要______共识，博物馆讲解员把大家的心拢到一起。", "options": ["凝结", "凝固", "冻住", "凝聚"], "answer": 3, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。"}, {"id": "yy-18644", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，把监督防线扎到最基层，社区规划师走村入户听民声。", "options": ["织密", "缝密", "织补", "织厚"], "answer": 0, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选A。"}, {"id": "yy-18645", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "这些年，新区建设的宏伟蓝图已经展开，设计师正把一张张蓝图变成施工图。", "options": ["耕耘", "修筑", "编织", "绘就"], "answer": 3, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选D。"}, {"id": "yy-18646", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "盛夏时节，放宽准入激发创业热情，税务干部让创造活力。", "options": ["涌出", "淌出", "涌流", "流出"], "answer": 2, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选C。"}, {"id": "yy-18647", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近期，内生动力从哪里来？电力工人把功夫下在创新上。", "options": ["增添", "增大", "增强", "加强"], "answer": 2, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选C。"}, {"id": "yy-18648", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "初秋时节，金杯银杯不如老百姓的口碑，志愿者们把每件小事都当大事办。", "options": ["设立", "创立", "树立", "建立"], "answer": 2, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选C。"}, {"id": "yy-18649", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "岁末年初，卡脖子技术亟待攻坚，青年学子集中力量______一个个瓶颈。", "options": ["突破", "捅破", "撞破", "冲破"], "answer": 0, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。"}, {"id": "yy-18650", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，靠山吃山靠水吃水，消防员因地制宜______资源优势。", "options": ["施展", "发扬", "发挥", "发展"], "answer": 2, "explanation": "「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选C。"}, {"id": "yy-18651", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，老旧小区加装电梯、增设车位，医护人员尽力______居民多样需求。", "options": ["满足", "满意", "充足", "充盈"], "answer": 0, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。"}, {"id": "yy-18652", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，数据孤岛必须连起来，医护人员下决心______部门间的壁垒。", "options": ["打碎", "击碎", "砸破", "打破"], "answer": 3, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。"}, {"id": "yy-18653", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "开春以来，危难时刻冲得上去，消防员的行动______了共产党员的担当。", "options": ["彰显", "显露", "暴露", "显摆"], "answer": 0, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。"}, {"id": "yy-18654", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，市场细胞活跃起来，执法人员让经济肌体活力。", "options": ["装满", "充满", "塞满", "填满"], "answer": 1, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。"}, {"id": "yy-18655", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，急难险重任务面前，法官主动______最重的责任。", "options": ["扛起", "抬起", "挑起", "背起"], "answer": 0, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选A。"}, {"id": "yy-18656", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，邻里纠纷无小事，驻村干部用真心______一件件矛盾。", "options": ["消融", "瓦解", "解开", "化解"], "answer": 3, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。"}, {"id": "yy-18657", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "岁末年初，乡情是最深的牵挂，电力工人以商会为平台______情感纽带。", "options": ["织牢", "系牢", "绑牢", "捆牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18658", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "开春以来，把消费潜力转化为增长实绩，非遗传承人拿出了实招硬招。", "options": ["发泄", "释放", "喷发", "散发"], "answer": 1, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选B。"}, {"id": "yy-18659", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "近年来，让公共服务覆盖城乡，消防员持续______政策体系。", "options": ["修完", "完缮", "补完", "完善"], "answer": 3, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。"}, {"id": "yy-18660", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "岁末年初，把监督防线扎到最基层，手工艺人走村入户听民声。", "options": ["织密", "织补", "缝密", "织厚"], "answer": 0, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选A。"}, {"id": "yy-18661", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "连日来，脱贫不是终点，工程师多措并举______脱贫成果。", "options": ["巩固", "加固", "稳固", "凝固"], "answer": 0, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。"}, {"id": "yy-18662", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "盛夏时节，邻里纠纷无小事，手工艺人用真心______一件件矛盾。", "options": ["消融", "解开", "化解", "瓦解"], "answer": 2, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。"}, {"id": "yy-18663", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "开春以来，产业发展的根基越牢，抗风险的能力就越强，工程师深谙此理，先把根基打扎实。", "options": ["铺设", "垒砌", "夯实", "敲打"], "answer": 2, "explanation": "「夯实」与「根基」搭配得当。「夯实根基」为固定搭配；「敲打」为具体动作；「铺设」用于管线、路面；「垒砌」用于砖石墙体。故选C。"}, {"id": "yy-18664", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，危难时刻冲得上去，工程师的行动______了共产党员的担当。", "options": ["彰显", "显摆", "暴露", "显露"], "answer": 0, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选A。"}, {"id": "yy-18665", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "这些年，改革到了深水区，治沙工人以钉钉子精神______工作局面。", "options": ["打开", "掀开", "翻开", "揭开"], "answer": 0, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。"}, {"id": "yy-18666", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "连日来，初心如磐，使命在肩，快递员把承诺落到一件件小事上。", "options": ["旅行", "践行", "履行", "执行"], "answer": 1, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选B。"}, {"id": "yy-18667", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，众人的事情由众人商量，农技人员把各方______到规划图上。", "options": ["聚拢", "收拢", "归拢", "凝聚"], "answer": 3, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选D。"}, {"id": "yy-18668", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，脱贫不是终点，文旅部门多措并举______脱贫成果。", "options": ["巩固", "加固", "凝固", "稳固"], "answer": 0, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。"}, {"id": "yy-18669", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "连日来，几十年如一日，设计师在平凡岗位上______着为民初心。", "options": ["坚守", "保守", "把守", "守卫"], "answer": 0, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选A。"}, {"id": "yy-18670", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，景区客流高峰来临，手工艺人全员上岗______游览秩序。", "options": ["维护", "维持", "保护", "护卫"], "answer": 0, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选A。"}, {"id": "yy-18671", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "今年以来，改革到了深水区，社区规划师以钉钉子精神______工作局面。", "options": ["打开", "掀开", "翻开", "揭开"], "answer": 0, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。"}, {"id": "yy-18672", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "初秋时节，金融活水精准滴灌，调解员为小微企业______发展动力。", "options": ["灌入", "注入", "灌输", "输入"], "answer": 1, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选B。"}, {"id": "yy-18673", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "岁末年初，一年一度的民生大考结束，博物馆讲解员向群众______了温暖的答卷。", "options": ["呈报", "递交", "上缴", "交出"], "answer": 3, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选D。"}, {"id": "yy-18674", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "连日来，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["铲平", "破除", "捣毁", "拆除"], "answer": 1, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选B。"}, {"id": "yy-18675", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "初秋时节，景区客流高峰来临，护林员全员上岗______游览秩序。", "options": ["维持", "护卫", "维护", "保护"], "answer": 2, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选C。"}, {"id": "yy-18676", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，众人的事情由众人商量，乡村医生把各方______到规划图上。", "options": ["收拢", "凝聚", "聚拢", "归拢"], "answer": 1, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选B。"}, {"id": "yy-18677", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近期，民生领域还有欠账，网格员列出清单逐项______短板。", "options": ["贴补", "补丁", "修补", "补齐"], "answer": 3, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选D。"}, {"id": "yy-18678", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，让公共服务覆盖城乡，茶农持续______政策体系。", "options": ["完缮", "补完", "修完", "完善"], "answer": 3, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。"}, {"id": "yy-18679", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，改革到了深水区，调解员以钉钉子精神______工作局面。", "options": ["打开", "翻开", "掀开", "揭开"], "answer": 0, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选A。"}, {"id": "yy-18680", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，被动状态必须改变，医护人员用硬措施______了不利局面。", "options": ["扭转", "反转", "倒转", "回转"], "answer": 0, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选A。"}, {"id": "yy-18681", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "入冬以来，脱贫不是终点，医护人员多措并举______脱贫成果。", "options": ["稳固", "加固", "巩固", "凝固"], "answer": 2, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选C。"}, {"id": "yy-18682", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近期，让新业态释放新动能，科研人员在制度创新上先行先试。", "options": ["激发", "引爆", "发动", "点燃"], "answer": 0, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选A。"}, {"id": "yy-18683", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，几十年如一日，手工艺人在平凡岗位上______着为民初心。", "options": ["守卫", "保守", "坚守", "把守"], "answer": 2, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选C。"}, {"id": "yy-18684", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "开春以来，筑起生态安全屏障，基层干部让青山常在绿水长流。", "options": ["筑牢", "锁牢", "砌牢", "拴牢"], "answer": 0, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选A。"}, {"id": "yy-18685", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，春潮拍岸千帆竞，税务干部感受到创新活力。", "options": ["淌动", "涌出", "流出", "涌动"], "answer": 3, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选D。"}, {"id": "yy-18686", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，齐抓共管不是一句口号，电力工人推动齐抓共管合力。", "options": ["成形", "成立", "形成", "成型"], "answer": 2, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选C。"}, {"id": "yy-18687", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "眼下，红色资源是最生动的教材，图书管理员让红色血脉代代相传。", "options": ["延续", "继续", "赓续", "接续"], "answer": 2, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选C。"}, {"id": "yy-18688", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "入冬以来，把监督防线扎到最基层，茶农走村入户听民声。", "options": ["缝密", "织厚", "织补", "织密"], "answer": 3, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选D。"}, {"id": "yy-18689", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，卡脖子技术亟待攻坚，消防员集中力量______一个个瓶颈。", "options": ["撞破", "突破", "冲破", "捅破"], "answer": 1, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选B。"}, {"id": "yy-18690", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，每个孩子都有闪光点，农技人员善于______学生潜能。", "options": ["挖掘", "掘取", "挖出", "开采"], "answer": 0, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选A。"}, {"id": "yy-18691", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "盛夏时节，齐抓共管不是一句口号，社区工作者推动齐抓共管合力。", "options": ["形成", "成形", "成型", "成立"], "answer": 0, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选A。"}, {"id": "yy-18692", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "初秋时节，老旧小区加装电梯、增设车位，工程师尽力______居民多样需求。", "options": ["满足", "充足", "充盈", "满意"], "answer": 0, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。"}, {"id": "yy-18693", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "眼下，民生实事清单公示上墙，社区规划师一件一件______承诺。", "options": ["实现", "完成", "达成", "兑现"], "answer": 3, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选D。"}, {"id": "yy-18694", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "初秋时节，民生实事清单公示上墙，民警一件一件______承诺。", "options": ["兑现", "实现", "完成", "达成"], "answer": 0, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选A。"}, {"id": "yy-18695", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "连日来，红色资源是最生动的教材，环卫工人让红色血脉代代相传。", "options": ["接续", "赓续", "延续", "继续"], "answer": 1, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选B。"}, {"id": "yy-18696", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "一段时间以来，一次次说到做到，社区工作者用行动______了群众的信任。", "options": ["获得", "赢得", "换取", "博得"], "answer": 1, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选B。"}, {"id": "yy-18697", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "近年来，誓师大会上，手工艺人精神斗志，誓言响彻训练场。", "options": ["昂扬", "高涨", "高昂", "高扬"], "answer": 0, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选A。"}, {"id": "yy-18698", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，一年一度的民生大考结束，程序员向群众______了温暖的答卷。", "options": ["呈报", "交出", "递交", "上缴"], "answer": 1, "explanation": "「交出」与「答卷」搭配得当。「交出答卷」为惯用搭配；「递交」多与申请、辞呈搭配；「呈报」多与公文搭配且含上下级意味；「上缴」多与款项、物品搭配。故选B。"}, {"id": "yy-18699", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "连日来，金杯银杯不如老百姓的口碑，审计人员把每件小事都当大事办。", "options": ["建立", "树立", "设立", "创立"], "answer": 1, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。"}, {"id": "yy-18700", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，市场细胞活跃起来，基层干部让经济肌体活力。", "options": ["充满", "装满", "塞满", "填满"], "answer": 0, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选A。"}, {"id": "yy-18701", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近年来，在广袤乡野间，程序员用汗水______出乡村振兴的崭新篇章。", "options": ["书写", "誊写", "抄写", "描红"], "answer": 0, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选A。"}, {"id": "yy-18702", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，小哨兵大作用，审计人员让基层网格______更大作用。", "options": ["施展", "发扬", "表现", "发挥"], "answer": 3, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选D。"}, {"id": "yy-18703", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "开春以来，向存量要效益，果农为产业升级______新空间。", "options": ["展开", "开展", "拓开", "拓展"], "answer": 3, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选D。"}, {"id": "yy-18704", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "近年来，内生动力从哪里来？市场监管部门把功夫下在创新上。", "options": ["增添", "增强", "加强", "增大"], "answer": 1, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。"}, {"id": "yy-18705", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "这些年，把监督防线扎到最基层，审计人员走村入户听民声。", "options": ["织厚", "织补", "织密", "缝密"], "answer": 2, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选C。"}, {"id": "yy-18706", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，人才是创新的第一资源，茶农把发展根基越培越厚。", "options": ["培土", "厚植", "浇灌", "施肥"], "answer": 1, "explanation": "「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选B。"}, {"id": "yy-18707", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近期，市场细胞活跃起来，乡村医生让经济肌体活力。", "options": ["塞满", "充满", "填满", "装满"], "answer": 1, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选B。"}, {"id": "yy-18708", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "这些年，初心如磐，使命在肩，教师把承诺落到一件件小事上。", "options": ["执行", "履行", "践行", "旅行"], "answer": 2, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。"}, {"id": "yy-18709", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "岁末年初，几十年如一日，茶农在平凡岗位上______着为民初心。", "options": ["保守", "把守", "坚守", "守卫"], "answer": 2, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选C。"}, {"id": "yy-18710", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，两岸同胞亲情割不断，消防员为青年交流______心灵心桥。", "options": ["铺设", "垒砌", "架起", "修筑"], "answer": 2, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选C。"}, {"id": "yy-18711", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "眼下，齐抓共管不是一句口号，网格员推动齐抓共管合力。", "options": ["形成", "成型", "成形", "成立"], "answer": 0, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选A。"}, {"id": "yy-18712", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "开春以来，景区客流高峰来临，渔民全员上岗______游览秩序。", "options": ["维护", "保护", "维持", "护卫"], "answer": 0, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选A。"}, {"id": "yy-18713", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，卡脖子技术亟待攻坚，渔民集中力量______一个个瓶颈。", "options": ["突破", "冲破", "撞破", "捅破"], "answer": 0, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选A。"}, {"id": "yy-18714", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "连日来，初心如磐，使命在肩，图书管理员把承诺落到一件件小事上。", "options": ["旅行", "履行", "践行", "执行"], "answer": 2, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。"}, {"id": "yy-18715", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "一段时间以来，订单排到明年，社区工作者发展的信心。", "options": ["倍受", "倍增", "倍加", "加倍"], "answer": 1, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选B。"}, {"id": "yy-18716", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，数据孤岛必须连起来，治沙工人下决心______部门间的壁垒。", "options": ["打碎", "砸破", "击碎", "打破"], "answer": 3, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选D。"}, {"id": "yy-18717", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，齐抓共管不是一句口号，医护人员推动齐抓共管合力。", "options": ["成型", "成立", "成形", "形成"], "answer": 3, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选D。"}, {"id": "yy-18718", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "眼下，二十年只做一件事，青年学子在细分领域里做到极致。", "options": ["深耕", "深挖", "深掘", "深钻"], "answer": 0, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选A。"}, {"id": "yy-18719", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "今年以来，把资源优势变成产业优势，市场监管部门下大气力______区域品牌。", "options": ["拍打", "打制", "锻打", "打造"], "answer": 3, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选D。"}, {"id": "yy-18720", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "入冬以来，城乡公共服务仍有落差，公交司机以实策逐步______差距。", "options": ["减少", "缩减", "缩小", "减小"], "answer": 2, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。"}, {"id": "yy-18721", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "这些年，初心如磐，使命在肩，执法人员把承诺落到一件件小事上。", "options": ["践行", "旅行", "执行", "履行"], "answer": 0, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。"}, {"id": "yy-18722", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "开春以来，老旧小区加装电梯、增设车位，快递员尽力______居民多样需求。", "options": ["充盈", "满意", "充足", "满足"], "answer": 3, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。"}, {"id": "yy-18723", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "一段时间以来，乡情是最深的牵挂，志愿者们以商会为平台______情感纽带。", "options": ["捆牢", "系牢", "绑牢", "织牢"], "answer": 3, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选D。"}, {"id": "yy-18724", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "连日来，越是众声喧哗，越需要______共识，社区规划师把大家的心拢到一起。", "options": ["凝固", "凝结", "冻住", "凝聚"], "answer": 3, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。"}, {"id": "yy-18725", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "今年以来，一次次说到做到，博物馆讲解员用行动______了群众的信任。", "options": ["换取", "博得", "赢得", "获得"], "answer": 2, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。"}, {"id": "yy-18726", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "初秋时节，把监督防线扎到最基层，老党员走村入户听民声。", "options": ["织厚", "缝密", "织补", "织密"], "answer": 3, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选D。"}, {"id": "yy-18727", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，老旧小区加装电梯、增设车位，文旅部门尽力______居民多样需求。", "options": ["满足", "充盈", "充足", "满意"], "answer": 0, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。"}, {"id": "yy-18728", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，被动状态必须改变，渔民用硬措施______了不利局面。", "options": ["反转", "倒转", "回转", "扭转"], "answer": 3, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。"}, {"id": "yy-18729", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "岁末年初，营商环境就是生产力，消防员让企业成长有沃土。", "options": ["培植", "培养", "厚植", "培育"], "answer": 2, "explanation": "「厚植」与「沃土」搭配得当。「厚植沃土」为书面惯用搭配；「培植」多与势力搭配含贬义；「培育」多与人才、市场搭配；「培养」多与人才搭配。故选C。"}, {"id": "yy-18730", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，春潮拍岸千帆竞，执法人员感受到创新活力。", "options": ["涌出", "涌动", "流出", "淌动"], "answer": 1, "explanation": "「涌动」与「活力」搭配得当。「活力涌动」为惯用表达；「涌出」「流出」为具体动作；「淌动」非规范。故选B。"}, {"id": "yy-18731", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "盛夏时节，一网通办让数据多跑路，科研人员以流程再造______政务效能。", "options": ["提高", "抬高", "提升", "拔高"], "answer": 2, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选C。"}, {"id": "yy-18732", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "入冬以来，市场细胞活跃起来，调解员让经济肌体活力。", "options": ["塞满", "装满", "充满", "填满"], "answer": 2, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选C。"}, {"id": "yy-18733", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "一段时间以来，老厂房变身文创园，基层干部让工业遗存______新的活力。", "options": ["焕发", "更新", "焕新", "换发"], "answer": 0, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选A。"}, {"id": "yy-18734", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "眼下，绿水青山就是金山银山，手工艺人代代接力______绿色生态。", "options": ["守望", "守候", "守护", "看守"], "answer": 2, "explanation": "「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选C。"}, {"id": "yy-18735", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，越是爬坡过坎，越要______必胜信心，乡村医生一步一个脚印向前走。", "options": ["坚决", "坚持不懈", "坚强", "坚定"], "answer": 3, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选D。"}, {"id": "yy-18736", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "开春以来，让公共服务覆盖城乡，博物馆讲解员持续______政策体系。", "options": ["完缮", "补完", "修完", "完善"], "answer": 3, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选D。"}, {"id": "yy-18737", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，老艺人收徒授艺，让千年技艺薪火。", "options": ["互传", "传递", "递送", "相传"], "answer": 3, "explanation": "「相传」与「薪火」搭配得当。「薪火相传」为固定成语；「互传」「递送」「传递」均无此搭配且丢失比喻义。故选D。"}, {"id": "yy-18738", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，几十年如一日，程序员在平凡岗位上______着为民初心。", "options": ["守卫", "保守", "把守", "坚守"], "answer": 3, "explanation": "「坚守」与「初心」搭配得当。「坚守初心」为固定搭配；「保守」多与秘密搭配；「守卫」用于边疆、家园；「把守」用于关口。故选D。"}, {"id": "yy-18739", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，传统村落保护性开发，消防员既富了口袋，也______了乡愁。", "options": ["扣留", "拘留", "留住", "截留"], "answer": 2, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选C。"}, {"id": "yy-18740", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "今年以来，停车难是城市治理的老大难，志愿者们用共享思维______了这一难题。", "options": ["解开", "破解", "解释", "解冻"], "answer": 1, "explanation": "「破解」与「难题」搭配得当。「破解难题」为固定搭配；「解开」多与绳结、心结搭配；「解冻」用于资产、关系；「解释」为说明缘由。故选B。"}, {"id": "yy-18741", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，改革到了深水区，博物馆讲解员以钉钉子精神______工作局面。", "options": ["掀开", "翻开", "揭开", "打开"], "answer": 3, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选D。"}, {"id": "yy-18742", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "初秋时节，内生动力从哪里来？护林员把功夫下在创新上。", "options": ["增大", "增强", "加强", "增添"], "answer": 1, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。"}, {"id": "yy-18743", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，众人的事情由众人商量，法官把各方______到规划图上。", "options": ["凝聚", "收拢", "归拢", "聚拢"], "answer": 0, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选A。"}, {"id": "yy-18744", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，发展为了人民，税务干部把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增进", "增加", "增添", "增殖"], "answer": 0, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选A。"}, {"id": "yy-18745", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "这些年，市场细胞活跃起来，医护人员让经济肌体活力。", "options": ["充满", "填满", "塞满", "装满"], "answer": 0, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选A。"}, {"id": "yy-18746", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "近期，让新业态释放新动能，农技人员在制度创新上先行先试。", "options": ["引爆", "激发", "点燃", "发动"], "answer": 1, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选B。"}, {"id": "yy-18747", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "眼下，金杯银杯不如老百姓的口碑，茶农把每件小事都当大事办。", "options": ["创立", "树立", "建立", "设立"], "answer": 1, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。"}, {"id": "yy-18748", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "初秋时节，危难时刻冲得上去，护林员的行动______了共产党员的担当。", "options": ["显摆", "暴露", "显露", "彰显"], "answer": 3, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选D。"}, {"id": "yy-18749", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，让要素流动更顺畅，就要______体制机制的藩篱。", "options": ["破除", "捣毁", "拆除", "铲平"], "answer": 0, "explanation": "「破除」与「藩篱」搭配得当。「破除藩篱」为固定搭配；「拆除」用于建筑；「铲平」用于场地；「捣毁」用于巢穴、据点且含暴力义。故选A。"}, {"id": "yy-18750", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，被动状态必须改变，志愿者们用硬措施______了不利局面。", "options": ["反转", "回转", "倒转", "扭转"], "answer": 3, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选D。"}, {"id": "yy-18751", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，邻里纠纷无小事，社区规划师用真心______一件件矛盾。", "options": ["解开", "瓦解", "消融", "化解"], "answer": 3, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选D。"}, {"id": "yy-18752", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近年来，誓师大会上，科研人员精神斗志，誓言响彻训练场。", "options": ["高扬", "昂扬", "高涨", "高昂"], "answer": 1, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选B。"}, {"id": "yy-18753", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "初秋时节，民生实事清单公示上墙，教师一件一件______承诺。", "options": ["实现", "达成", "兑现", "完成"], "answer": 2, "explanation": "「兑现」与「承诺」搭配得当。「兑现承诺」为固定搭配；「实现」多与梦想、目标搭配；「完成」多与任务搭配；「达成」多与协议搭配。故选C。"}, {"id": "yy-18754", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，发展为了人民，图书管理员把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增进", "增添", "增加", "增殖"], "answer": 0, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选A。"}, {"id": "yy-18755", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，把监督防线扎到最基层，快递员走村入户听民声。", "options": ["织厚", "织补", "缝密", "织密"], "answer": 3, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选D。"}, {"id": "yy-18756", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近期，数据孤岛必须连起来，图书管理员下决心______部门间的壁垒。", "options": ["打破", "打碎", "砸破", "击碎"], "answer": 0, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。"}, {"id": "yy-18757", "module": "yanyu", "diff": 1, "exam": "医疗编", "prompt": "连日来，两岸同胞亲情割不断，审计人员为青年交流______心灵心桥。", "options": ["修筑", "架起", "铺设", "垒砌"], "answer": 1, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。"}, {"id": "yy-18758", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "盛夏时节，改革红利持续显现，市场活力不断，茶农信心更足。", "options": ["暴发", "突发", "爆发", "迸发"], "answer": 3, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选D。"}, {"id": "yy-18759", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "近期，老工业基地涅槃重生，驻村干部加快新旧动能步伐。", "options": ["转换", "转变", "变换", "改换"], "answer": 0, "explanation": "「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选A。"}, {"id": "yy-18760", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，筑起生态安全屏障，农技人员让青山常在绿水长流。", "options": ["筑牢", "砌牢", "拴牢", "锁牢"], "answer": 0, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选A。"}, {"id": "yy-18761", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，把家国情怀融入课堂，志愿者们用身边故事打动学生。", "options": ["厚植", "培土", "施肥", "浇灌"], "answer": 0, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选A。"}, {"id": "yy-18762", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，市场不是法外之地，消防员以制度______交易秩序。", "options": ["规定", "规正", "规范", "规整"], "answer": 2, "explanation": "「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选C。"}, {"id": "yy-18763", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，越是众声喧哗，越需要______共识，志愿者们把大家的心拢到一起。", "options": ["凝聚", "凝结", "凝固", "冻住"], "answer": 0, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选A。"}, {"id": "yy-18764", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "今年以来，数据孤岛必须连起来，民警下决心______部门间的壁垒。", "options": ["打破", "打碎", "击碎", "砸破"], "answer": 0, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。"}, {"id": "yy-18765", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "眼下，纪律规矩挺在前面，青年学子始终______纪律底线。", "options": ["看守", "遵守", "严守", "把守"], "answer": 2, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选C。"}, {"id": "yy-18766", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "连日来，红色资源是最生动的教材，医护人员让红色血脉代代相传。", "options": ["接续", "延续", "赓续", "继续"], "answer": 2, "explanation": "「赓续」与「血脉」搭配得当。「赓续血脉」为书面惯用搭配；「继续」为一般动词；「接续」多与手续、产业搭配；「延续」多与生命、文脉搭配。故选C。"}, {"id": "yy-18767", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，把资源优势变成产业优势，博物馆讲解员下大气力______区域品牌。", "options": ["拍打", "打制", "锻打", "打造"], "answer": 3, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选D。"}, {"id": "yy-18768", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，齐抓共管不是一句口号，图书管理员推动齐抓共管合力。", "options": ["形成", "成立", "成形", "成型"], "answer": 0, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选A。"}, {"id": "yy-18769", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，越是众声喧哗，越需要______共识，非遗传承人把大家的心拢到一起。", "options": ["凝聚", "凝固", "凝结", "冻住"], "answer": 0, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选A。"}, {"id": "yy-18770", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，每个孩子都有闪光点，驻村干部善于______学生潜能。", "options": ["开采", "掘取", "挖出", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18771", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，改革红利持续显现，市场活力不断，非遗传承人信心更足。", "options": ["暴发", "突发", "迸发", "爆发"], "answer": 2, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。"}, {"id": "yy-18772", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "初秋时节，跳出一时一地看发展，公交司机着力______开放共赢的新格局。", "options": ["架造", "构建", "搭造", "构作"], "answer": 1, "explanation": "「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选B。"}, {"id": "yy-18773", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "初秋时节，汛期将至，电力工人对辖区地质灾害隐患逐点______。", "options": ["排查", "检察", "普查", "检查"], "answer": 0, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选A。"}, {"id": "yy-18774", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "今年以来，手握核心技术专利，公交司机创新的底气。", "options": ["更强", "更壮", "更硬", "更足"], "answer": 3, "explanation": "「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选D。"}, {"id": "yy-18775", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "入冬以来，齐抓共管不是一句口号，文旅部门推动齐抓共管合力。", "options": ["成立", "形成", "成形", "成型"], "answer": 1, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选B。"}, {"id": "yy-18776", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "这些年，一网通办让数据多跑路，青年学子以流程再造______政务效能。", "options": ["提升", "拔高", "抬高", "提高"], "answer": 0, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选A。"}, {"id": "yy-18777", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "这些年，民生领域还有欠账，公交司机列出清单逐项______短板。", "options": ["修补", "补齐", "贴补", "补丁"], "answer": 1, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。"}, {"id": "yy-18778", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "眼下，汛期将至，调解员对辖区地质灾害隐患逐点______。", "options": ["检察", "排查", "普查", "检查"], "answer": 1, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。"}, {"id": "yy-18779", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，二十年只做一件事，审计人员在细分领域里做到极致。", "options": ["深掘", "深耕", "深挖", "深钻"], "answer": 1, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选B。"}, {"id": "yy-18780", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "开春以来，初心如磐，使命在肩，网格员把承诺落到一件件小事上。", "options": ["旅行", "践行", "履行", "执行"], "answer": 1, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选B。"}, {"id": "yy-18781", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "一段时间以来，每个孩子都有闪光点，民警善于______学生潜能。", "options": ["挖出", "掘取", "挖掘", "开采"], "answer": 2, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选C。"}, {"id": "yy-18782", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，改革到了深水区，设计师以钉钉子精神______工作局面。", "options": ["揭开", "翻开", "打开", "掀开"], "answer": 2, "explanation": "「打开」与「局面」搭配得当。「打开局面」为固定搭配；「翻开」用于书页；「揭开」多与谜底、序幕搭配；「掀开」用于盖子、帘子。故选C。"}, {"id": "yy-18783", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "眼下，景区客流高峰来临，电力工人全员上岗______游览秩序。", "options": ["护卫", "维护", "保护", "维持"], "answer": 1, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选B。"}, {"id": "yy-18784", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "连日来，汛期将至，乡村医生对辖区地质灾害隐患逐点______。", "options": ["检察", "排查", "检查", "普查"], "answer": 1, "explanation": "「排查」与「隐患」搭配得当。「排查隐患」为固定搭配，强调逐一清查；「检查」为一般查看；「检察」为法律监督专用；「普查」为全面调查登记。故选B。"}, {"id": "yy-18785", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "入冬以来，急难险重任务面前，税务干部主动______最重的责任。", "options": ["挑起", "扛起", "背起", "抬起"], "answer": 1, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选B。"}, {"id": "yy-18786", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "初秋时节，急难险重任务面前，基层干部主动______最重的责任。", "options": ["挑起", "抬起", "背起", "扛起"], "answer": 3, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选D。"}, {"id": "yy-18787", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，内生动力从哪里来？广大建设者把功夫下在创新上。", "options": ["增强", "增添", "加强", "增大"], "answer": 0, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选A。"}, {"id": "yy-18788", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，市场细胞活跃起来，驻村干部让经济肌体活力。", "options": ["充满", "填满", "装满", "塞满"], "answer": 0, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选A。"}, {"id": "yy-18789", "module": "yanyu", "diff": 3, "exam": "教师编", "prompt": "岁末年初，人才是创新的第一资源，环卫工人把发展根基越培越厚。", "options": ["浇灌", "厚植", "施肥", "培土"], "answer": 1, "explanation": "「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选B。"}, {"id": "yy-18790", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，手握核心技术专利，调解员创新的底气。", "options": ["更硬", "更足", "更壮", "更强"], "answer": 1, "explanation": "「更足」与「底气」搭配得当。「底气更足」为惯用搭配；「更硬」多与作风搭配；「更强」多与实力搭配；「更壮」用于体格。故选B。"}, {"id": "yy-18791", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "入冬以来，初心如磐，使命在肩，农技人员把承诺落到一件件小事上。", "options": ["践行", "旅行", "履行", "执行"], "answer": 0, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。"}, {"id": "yy-18792", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，金杯银杯不如老百姓的口碑，广大建设者把每件小事都当大事办。", "options": ["建立", "设立", "创立", "树立"], "answer": 3, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选D。"}, {"id": "yy-18793", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，在广袤乡野间，审计人员用汗水______出乡村振兴的崭新篇章。", "options": ["抄写", "描红", "誊写", "书写"], "answer": 3, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。"}, {"id": "yy-18794", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，政府、市场、社会同向发力，农技人员让各方______成强大合力。", "options": ["汇合", "汇聚", "汇集", "聚合"], "answer": 1, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选B。"}, {"id": "yy-18795", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，越是众声喧哗，越需要______共识，工程师把大家的心拢到一起。", "options": ["冻住", "凝固", "凝结", "凝聚"], "answer": 3, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选D。"}, {"id": "yy-18796", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，传统村落保护性开发，青年学子既富了口袋，也______了乡愁。", "options": ["扣留", "留住", "拘留", "截留"], "answer": 1, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选B。"}, {"id": "yy-18797", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，乡情是最深的牵挂，调解员以商会为平台______情感纽带。", "options": ["织牢", "系牢", "绑牢", "捆牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18798", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，发展为了人民，渔民把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增添", "增加", "增殖", "增进"], "answer": 3, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。"}, {"id": "yy-18799", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，从受理到反馈全流程留痕，社区工作者以数字化手段______管理闭环。", "options": ["构画", "构建", "搭圈", "圈画"], "answer": 1, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。"}, {"id": "yy-18800", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "入冬以来，把风险挺在前面，非遗传承人织密织牢安全网。", "options": ["防守", "提防", "防备", "防范"], "answer": 3, "explanation": "「防范」与「风险」搭配得当。「防范风险」为固定搭配；「防备」侧重有所准备；「提防」为口语化小心在意；「防守」多用于比赛、军事。故选D。"}, {"id": "yy-18801", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "入冬以来，被动状态必须改变，农技人员用硬措施______了不利局面。", "options": ["反转", "回转", "扭转", "倒转"], "answer": 2, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选C。"}, {"id": "yy-18802", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，每个孩子都有闪光点，民警善于______学生潜能。", "options": ["掘取", "开采", "挖出", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18803", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "岁末年初，老旧小区加装电梯、增设车位，农技人员尽力______居民多样需求。", "options": ["充足", "满足", "充盈", "满意"], "answer": 1, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选B。"}, {"id": "yy-18804", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "今年以来，景区客流高峰来临，农技人员全员上岗______游览秩序。", "options": ["保护", "护卫", "维护", "维持"], "answer": 2, "explanation": "「维护」与「秩序」搭配得当。「维护秩序」为固定搭配；「维持」多与生活、现状搭配；「保护」多与权益、环境搭配；「护卫」用于人员、目标。故选C。"}, {"id": "yy-18805", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，从受理到反馈全流程留痕，果农以数字化手段______管理闭环。", "options": ["构画", "搭圈", "圈画", "构建"], "answer": 3, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选D。"}, {"id": "yy-18806", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "岁末年初，一二三产融合发展，执法人员推动产业链不断延伸。", "options": ["伸长", "拉长", "延长", "延伸"], "answer": 3, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。"}, {"id": "yy-18807", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "近年来，一网通办让数据多跑路，医护人员以流程再造______政务效能。", "options": ["提升", "拔高", "提高", "抬高"], "answer": 0, "explanation": "「提升」与「效能」搭配得当。「提升效能」为固定搭配；「提高」多与水平、价格搭配；「拔高」含刻意抬升义；「抬高」多与价格、身价搭配。故选A。"}, {"id": "yy-18808", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "眼下，政府、市场、社会同向发力，调解员让各方______成强大合力。", "options": ["汇合", "汇聚", "汇集", "聚合"], "answer": 1, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选B。"}, {"id": "yy-18809", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "今年以来，发展为了人民，教师把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增殖", "增添", "增进", "增加"], "answer": 2, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选C。"}, {"id": "yy-18810", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "眼下，一二三产融合发展，法官推动产业链不断延伸。", "options": ["拉长", "伸长", "延长", "延伸"], "answer": 3, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选D。"}, {"id": "yy-18811", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "盛夏时节，每一起案件都关乎群众对法治的信仰，老党员用公正裁判______正义。", "options": ["保卫", "护卫", "防御", "捍卫"], "answer": 3, "explanation": "「捍卫」与「公平」搭配得当。「捍卫公平」为书面惯用搭配；「保卫」多与祖国、和平搭配；「护卫」为护送守卫；「防御」用于军事、疫情。故选D。"}, {"id": "yy-18812", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "开春以来，让农产品出村进城，环卫工人多方合力______销售通道。", "options": ["扩宽", "拓宽", "开宽", "开辟"], "answer": 1, "explanation": "「拓宽」与「通道」搭配得当。「拓宽通道」为固定搭配；「开宽」非规范；「扩宽」多用于道路；「拓宽」亦用于道路但与渠道、通道搭配最常见。故选B。"}, {"id": "yy-18813", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "盛夏时节，把消费潜力转化为增长实绩，文旅部门拿出了实招硬招。", "options": ["释放", "散发", "喷发", "发泄"], "answer": 0, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。"}, {"id": "yy-18814", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "眼下，一次次说到做到，教师用行动______了群众的信任。", "options": ["博得", "获得", "赢得", "换取"], "answer": 2, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选C。"}, {"id": "yy-18815", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近期，小哨兵大作用，工程师让基层网格______更大作用。", "options": ["发扬", "施展", "发挥", "表现"], "answer": 2, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选C。"}, {"id": "yy-18816", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，乡情是最深的牵挂，公交司机以商会为平台______情感纽带。", "options": ["系牢", "绑牢", "捆牢", "织牢"], "answer": 3, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选D。"}, {"id": "yy-18817", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "入冬以来，老厂房变身文创园，青年学子让工业遗存______新的活力。", "options": ["焕新", "焕发", "更新", "换发"], "answer": 1, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选B。"}, {"id": "yy-18818", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "开春以来，市场不是法外之地，驻村干部以制度______交易秩序。", "options": ["规范", "规整", "规正", "规定"], "answer": 0, "explanation": "「规范」与「秩序」搭配得当。「规范秩序」为惯用搭配；「规定」为名词或动词制定；「规整」指整齐；「规正」指匡正。故选A。"}, {"id": "yy-18819", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，一次次说到做到，工程师用行动______了群众的信任。", "options": ["获得", "赢得", "博得", "换取"], "answer": 1, "explanation": "「赢得」与「信任」搭配得当。「赢得信任」为固定搭配，强调经努力而获得；「获得」中性；「博得」多与同情、喝彩搭配；「换取」含交换义。故选B。"}, {"id": "yy-18820", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "开春以来，从受理到反馈全流程留痕，老党员以数字化手段______管理闭环。", "options": ["搭圈", "构建", "构画", "圈画"], "answer": 1, "explanation": "「构建」与「闭环」搭配得当。「构建闭环」为惯用搭配；其余选项均非规范搭配。故选B。"}, {"id": "yy-18821", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "近年来，订单排到明年，科研人员发展的信心。", "options": ["倍增", "加倍", "倍加", "倍受"], "answer": 0, "explanation": "「倍增」与「信心」搭配得当。「信心倍增」为惯用搭配；「加倍」为动词或副词；「倍加」多与珍惜搭配；「倍受」多与关注搭配。故选A。"}, {"id": "yy-18822", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，越是众声喧哗，越需要______共识，志愿者们把大家的心拢到一起。", "options": ["凝聚", "凝固", "凝结", "冻住"], "answer": 0, "explanation": "「凝聚」与「共识」搭配得当。「凝聚共识」为固定搭配；「凝固」「冻住」「凝结」均为物理状态变化，用于抽象共识不当。故选A。"}, {"id": "yy-18823", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "初秋时节，在广袤乡野间，驻村干部用汗水______出乡村振兴的崭新篇章。", "options": ["书写", "描红", "誊写", "抄写"], "answer": 0, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选A。"}, {"id": "yy-18824", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近年来，两岸同胞亲情割不断，铁路养护工为青年交流______心灵心桥。", "options": ["修筑", "架起", "垒砌", "铺设"], "answer": 1, "explanation": "「架起」与「心桥」搭配得当。「架起心桥」为惯用比喻搭配；「修筑」用于道路工程；「垒砌」用于砖石；「铺设」用于管线轨道。故选B。"}, {"id": "yy-18825", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，老工业基地涅槃重生，消防员加快新旧动能步伐。", "options": ["转换", "改换", "变换", "转变"], "answer": 0, "explanation": "「转换」与「动能」搭配得当。「动能转换」为固定搭配；「转变」多与观念、方式搭配；「改换」「变换」多与门庭、姿势搭配。故选A。"}, {"id": "yy-18826", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，发展为了人民，治沙工人把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增殖", "增加", "增添", "增进"], "answer": 3, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。"}, {"id": "yy-18827", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "盛夏时节，减税降费政策落地，民警让企业真切感受到红利。", "options": ["发放", "释放", "散发", "发射"], "answer": 1, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选B。"}, {"id": "yy-18828", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，初心如磐，使命在肩，乡村医生把承诺落到一件件小事上。", "options": ["执行", "践行", "履行", "旅行"], "answer": 1, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选B。"}, {"id": "yy-18829", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近年来，乡情是最深的牵挂，环卫工人以商会为平台______情感纽带。", "options": ["织牢", "系牢", "捆牢", "绑牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18830", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近年来，把家国情怀融入课堂，非遗传承人用身边故事打动学生。", "options": ["厚植", "浇灌", "施肥", "培土"], "answer": 0, "explanation": "「厚植」与「情怀」搭配得当。「厚植情怀」为书面惯用搭配；「加深」多与印象、了解搭配。故选A。"}, {"id": "yy-18831", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "盛夏时节，乡情是最深的牵挂，执法人员以商会为平台______情感纽带。", "options": ["织牢", "捆牢", "系牢", "绑牢"], "answer": 0, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选A。"}, {"id": "yy-18832", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近期，让监督机制长出牙齿，护林员把制度笼子越扎越紧。", "options": ["修复", "健全", "修理", "修葺"], "answer": 1, "explanation": "「健全」与「机制」搭配得当。「健全机制」为固定搭配，使完善；「修理」「修复」「修葺」均指具体物件的修补，与机制不搭。故选B。"}, {"id": "yy-18833", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，初心如磐，使命在肩，设计师把承诺落到一件件小事上。", "options": ["旅行", "执行", "践行", "履行"], "answer": 2, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选C。"}, {"id": "yy-18834", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "开春以来，人才是创新的第一资源，茶农把发展根基越培越厚。", "options": ["培土", "浇灌", "厚植", "施肥"], "answer": 2, "explanation": "「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选C。"}, {"id": "yy-18835", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，急难险重任务面前，青年学子主动______最重的责任。", "options": ["挑起", "抬起", "扛起", "背起"], "answer": 2, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选C。"}, {"id": "yy-18836", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "岁末年初，安全底线不可逾越，博物馆讲解员24小时轮班值守。", "options": ["看守", "镇守", "把守", "坚守"], "answer": 3, "explanation": "「坚守」与「底线」搭配得当。「坚守底线」为固定搭配；「看守」「把守」「镇守」均指具体看护动作，多用于人员、关口、城池。故选D。"}, {"id": "yy-18837", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，万丈高楼平地起，乡村医生一锤一钎______发展基础。", "options": ["踩实", "填实", "夯实", "砸实"], "answer": 2, "explanation": "「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选C。"}, {"id": "yy-18838", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "入冬以来，脱贫不是终点，执法人员多措并举______脱贫成果。", "options": ["加固", "稳固", "巩固", "凝固"], "answer": 2, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选C。"}, {"id": "yy-18839", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "今年以来，誓师大会上，驻村干部精神斗志，誓言响彻训练场。", "options": ["高涨", "高昂", "高扬", "昂扬"], "answer": 3, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。"}, {"id": "yy-18840", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "连日来，让公共服务覆盖城乡，渔民持续______政策体系。", "options": ["补完", "修完", "完善", "完缮"], "answer": 2, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。"}, {"id": "yy-18841", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "盛夏时节，卡脖子技术亟待攻坚，青年学子集中力量______一个个瓶颈。", "options": ["撞破", "捅破", "冲破", "突破"], "answer": 3, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选D。"}, {"id": "yy-18842", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "眼下，小哨兵大作用，文旅部门让基层网格______更大作用。", "options": ["发挥", "发扬", "表现", "施展"], "answer": 0, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选A。"}, {"id": "yy-18843", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "初秋时节，市场细胞活跃起来，工程师让经济肌体活力。", "options": ["充满", "塞满", "装满", "填满"], "answer": 0, "explanation": "「充满」与「活力」搭配得当。「充满活力」为固定搭配；「填满」「塞满」「装满」均为具体动作，用于抽象活力不当。故选A。"}, {"id": "yy-18844", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "开春以来，古城修缮不搞大拆大建，渔民让千年文脉在街巷间静静流淌。", "options": ["接通", "续接", "连接", "延续"], "answer": 3, "explanation": "「延续」与「文脉」搭配得当。「延续文脉」为惯用搭配；「连接」指具体相连；「续接」多与线路搭配；「接通」用于电话、电路。故选D。"}, {"id": "yy-18845", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，邻里纠纷无小事，快递员用真心______一件件矛盾。", "options": ["消融", "解开", "化解", "瓦解"], "answer": 2, "explanation": "「化解」与「矛盾」搭配得当。「化解矛盾」为固定搭配；「解开」多与疙瘩、谜团搭配；「消融」用于冰雪；「瓦解」多用于组织、士气。故选C。"}, {"id": "yy-18846", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "入冬以来，城乡公共服务仍有落差，老党员以实策逐步______差距。", "options": ["减少", "缩减", "缩小", "减小"], "answer": 2, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选C。"}, {"id": "yy-18847", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，数据孤岛必须连起来，护林员下决心______部门间的壁垒。", "options": ["打碎", "砸破", "打破", "击碎"], "answer": 2, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选C。"}, {"id": "yy-18848", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "今年以来，传统村落保护性开发，工程师既富了口袋，也______了乡愁。", "options": ["扣留", "截留", "留住", "拘留"], "answer": 2, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选C。"}, {"id": "yy-18849", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "今年以来，誓师大会上，公交司机精神斗志，誓言响彻训练场。", "options": ["高涨", "高扬", "高昂", "昂扬"], "answer": 3, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。"}, {"id": "yy-18850", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "近年来，人才是创新的第一资源，消防员把发展根基越培越厚。", "options": ["施肥", "培土", "厚植", "浇灌"], "answer": 2, "explanation": "「厚植」与「根基」搭配得当。「厚植根基」为书面惯用搭配；「培土」「施肥」「浇灌」均为农事具体动作。故选C。"}, {"id": "yy-18851", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，纪律规矩挺在前面，税务干部始终______纪律底线。", "options": ["严守", "遵守", "看守", "把守"], "answer": 0, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选A。"}, {"id": "yy-18852", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，绿水青山就是金山银山，果农代代接力______绿色生态。", "options": ["守候", "守望", "守护", "看守"], "answer": 2, "explanation": "「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选C。"}, {"id": "yy-18853", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，众人的事情由众人商量，老党员把各方______到规划图上。", "options": ["收拢", "聚拢", "归拢", "凝聚"], "answer": 3, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选D。"}, {"id": "yy-18854", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "近年来，被动状态必须改变，铁路养护工用硬措施______了不利局面。", "options": ["扭转", "倒转", "回转", "反转"], "answer": 0, "explanation": "「扭转」与「局面」搭配得当。「扭转局面」为固定搭配；「反转」多与剧情、行情搭配；「倒转」「回转」指方向掉转。故选A。"}, {"id": "yy-18855", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "这些年，跳出一时一地看发展，社区规划师着力______开放共赢的新格局。", "options": ["搭造", "架造", "构作", "构建"], "answer": 3, "explanation": "「构建」与「格局」搭配得当。「构建格局」为惯用搭配；「构作」「搭造」「架造」均非规范书面搭配。故选D。"}, {"id": "yy-18856", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "连日来，筑起生态安全屏障，审计人员让青山常在绿水长流。", "options": ["筑牢", "拴牢", "锁牢", "砌牢"], "answer": 0, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选A。"}, {"id": "yy-18857", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "连日来，万丈高楼平地起，设计师一锤一钎______发展基础。", "options": ["砸实", "填实", "踩实", "夯实"], "answer": 3, "explanation": "「夯实」与「基础」搭配得当。「夯实基础」为固定搭配；「砸实」「踩实」「填实」均为具体动作。故选D。"}, {"id": "yy-18858", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，新区建设的宏伟蓝图已经展开，电力工人正把一张张蓝图变成施工图。", "options": ["绘就", "耕耘", "修筑", "编织"], "answer": 0, "explanation": "「绘就」与「蓝图」搭配得当。「绘就蓝图」为惯用搭配；「修筑」用于道路工事；「耕耘」用于田地或比喻辛勤付出；「编织」多与梦想、纽带搭配，与蓝图不搭。故选A。"}, {"id": "yy-18859", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "今年以来，向存量要效益，审计人员为产业升级______新空间。", "options": ["开展", "拓展", "展开", "拓开"], "answer": 1, "explanation": "「拓展」与「空间」搭配得当。「拓展空间」为固定搭配；「拓开」非规范；「开展」多与活动搭配；「展开」多与画卷、攻势搭配。故选B。"}, {"id": "yy-18860", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近年来，传统村落保护性开发，驻村干部既富了口袋，也______了乡愁。", "options": ["留住", "截留", "扣留", "拘留"], "answer": 0, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选A。"}, {"id": "yy-18861", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "这些年，政府、市场、社会同向发力，治沙工人让各方______成强大合力。", "options": ["聚合", "汇集", "汇聚", "汇合"], "answer": 2, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选C。"}, {"id": "yy-18862", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，减税降费政策落地，图书管理员让企业真切感受到红利。", "options": ["散发", "发射", "发放", "释放"], "answer": 3, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。"}, {"id": "yy-18863", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，让新业态释放新动能，快递员在制度创新上先行先试。", "options": ["点燃", "引爆", "发动", "激发"], "answer": 3, "explanation": "「激发」与「动能」搭配得当。「激发动能」为惯用搭配；「发动」多与机器、群众搭配；「点燃」多与激情搭配；「引爆」多与话题、舆论搭配且含突然义。故选D。"}, {"id": "yy-18864", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，城乡公共服务仍有落差，审计人员以实策逐步______差距。", "options": ["缩减", "减小", "减少", "缩小"], "answer": 3, "explanation": "「缩小」与「差距」搭配得当。「缩小差距」为固定搭配；「减少」多与数量搭配；「缩减」多与开支、编制搭配；「减小」多与阻力、噪音搭配。故选D。"}, {"id": "yy-18865", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "盛夏时节，危难时刻冲得上去，医护人员的行动______了共产党员的担当。", "options": ["显摆", "彰显", "暴露", "显露"], "answer": 1, "explanation": "「彰显」与「担当」搭配得当。「彰显担当」为固定搭配，褒义；「显摆」为口语含贬义；「显露」中性；「暴露」多含贬义。故选B。"}, {"id": "yy-18866", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，越是爬坡过坎，越要______必胜信心，护林员一步一个脚印向前走。", "options": ["坚定", "坚持不懈", "坚强", "坚决"], "answer": 0, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选A。"}, {"id": "yy-18867", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "岁末年初，脱贫不是终点，农技人员多措并举______脱贫成果。", "options": ["凝固", "加固", "稳固", "巩固"], "answer": 3, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选D。"}, {"id": "yy-18868", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，每个孩子都有闪光点，教师善于______学生潜能。", "options": ["掘取", "开采", "挖掘", "挖出"], "answer": 2, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选C。"}, {"id": "yy-18869", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，老旧小区加装电梯、增设车位，手工艺人尽力______居民多样需求。", "options": ["充足", "满意", "充盈", "满足"], "answer": 3, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选D。"}, {"id": "yy-18870", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近期，内生动力从哪里来？公交司机把功夫下在创新上。", "options": ["加强", "增强", "增添", "增大"], "answer": 1, "explanation": "「增强」与「动力」搭配得当。「增强动力」为固定搭配；「加强」多与领导、管理搭配；「增大」多与幅度、剂量搭配。故选B。"}, {"id": "yy-18871", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "开春以来，靠山吃山靠水吃水，茶农因地制宜______资源优势。", "options": ["发挥", "施展", "发展", "发扬"], "answer": 0, "explanation": "「发挥」与「优势」搭配得当。「发挥优势」为固定搭配；「发扬」多与精神、作风搭配；「发展」多与经济、事业搭配。故选A。"}, {"id": "yy-18872", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "一段时间以来，越是爬坡过坎，越要______必胜信心，消防员一步一个脚印向前走。", "options": ["坚决", "坚强", "坚定", "坚持不懈"], "answer": 2, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选C。"}, {"id": "yy-18873", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "盛夏时节，一二三产融合发展，社区规划师推动产业链不断延伸。", "options": ["延长", "延伸", "伸长", "拉长"], "answer": 1, "explanation": "「延伸」与「链条」搭配得当。「链条延伸」为惯用搭配；「伸长」「拉长」「延长」多用于具体长度或时间。故选B。"}, {"id": "yy-18874", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "眼下，齐抓共管不是一句口号，法官推动齐抓共管合力。", "options": ["成型", "成立", "成形", "形成"], "answer": 3, "explanation": "「形成」与「合力」搭配得当。「形成合力」为固定搭配；「成形」「成型」指具形；「成立」多与组织搭配。故选D。"}, {"id": "yy-18875", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "盛夏时节，誓师大会上，程序员精神斗志，誓言响彻训练场。", "options": ["高涨", "高昂", "高扬", "昂扬"], "answer": 3, "explanation": "「昂扬」与「斗志」搭配得当。「斗志昂扬」为固定成语；「高昂」多与情绪、价格搭配；「高涨」多与热情搭配；「高扬」多与旗帜搭配。故选D。"}, {"id": "yy-18876", "module": "yanyu", "diff": 1, "exam": "教师编", "prompt": "入冬以来，把监督防线扎到最基层，科研人员走村入户听民声。", "options": ["织厚", "织补", "缝密", "织密"], "answer": 3, "explanation": "「织密」与「防线」搭配得当。「织密防线」为惯用搭配；「织厚」「缝密」非规范搭配；「织补」指修补织物。故选D。"}, {"id": "yy-18877", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "一段时间以来，把消费潜力转化为增长实绩，环卫工人拿出了实招硬招。", "options": ["释放", "发泄", "散发", "喷发"], "answer": 0, "explanation": "「释放」与「潜力」搭配得当。「释放潜力」为固定搭配；「发泄」含贬义多与情绪搭配；「散发」多与气味、气息搭配；「喷发」用于火山或比喻爆发。故选A。"}, {"id": "yy-18878", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，纪律规矩挺在前面，果农始终______纪律底线。", "options": ["严守", "遵守", "看守", "把守"], "answer": 0, "explanation": "「严守」与「底线」搭配得当。「严守底线」为固定搭配；「看守」「把守」为具体看护；「遵守」多与规则、法律搭配。故选A。"}, {"id": "yy-18879", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "一段时间以来，急难险重任务面前，铁路养护工主动______最重的责任。", "options": ["抬起", "扛起", "挑起", "背起"], "answer": 1, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选B。"}, {"id": "yy-18880", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，面对转型路上的重重难关，公交司机迎难而上，把一个个难关逐一______。", "options": ["化解", "破除", "克服", "攻克"], "answer": 3, "explanation": "「攻克」与「难关」搭配得当。「攻克难关」为固定搭配，强调付出努力战而胜之；「克服」多与困难、缺点搭配；「破除」多与迷信、藩篱搭配；「化解」多与矛盾、风险搭配。故选D。"}, {"id": "yy-18881", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "初秋时节，越是爬坡过坎，越要______必胜信心，乡村医生一步一个脚印向前走。", "options": ["坚强", "坚定", "坚持不懈", "坚决"], "answer": 1, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选B。"}, {"id": "yy-18882", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "盛夏时节，放宽准入激发创业热情，消防员让创造活力。", "options": ["涌出", "淌出", "流出", "涌流"], "answer": 3, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选D。"}, {"id": "yy-18883", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，老厂房变身文创园，民警让工业遗存______新的活力。", "options": ["更新", "焕发", "焕新", "换发"], "answer": 1, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选B。"}, {"id": "yy-18884", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "这些年，金杯银杯不如老百姓的口碑，治沙工人把每件小事都当大事办。", "options": ["建立", "树立", "设立", "创立"], "answer": 1, "explanation": "「树立」与「口碑」搭配得当。「树立口碑」为惯用搭配；「建立」多与制度、关系搭配；「设立」多与机构搭配；「创立」多与学说、品牌搭配。故选B。"}, {"id": "yy-18885", "module": "yanyu", "diff": 3, "exam": "国考", "prompt": "眼下，绿水青山就是金山银山，治沙工人代代接力______绿色生态。", "options": ["守望", "守护", "守候", "看守"], "answer": 1, "explanation": "「守护」与「生态」搭配得当。「守护生态」为惯用搭配，含珍视呵护义；「看守」用于财物、门户；「守候」指等待；「守望」指瞭望盼望。故选B。"}, {"id": "yy-18886", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "岁末年初，把资源优势变成产业优势，渔民下大气力______区域品牌。", "options": ["打制", "打造", "锻打", "拍打"], "answer": 1, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选B。"}, {"id": "yy-18887", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "入冬以来，民生领域还有欠账，社区规划师列出清单逐项______短板。", "options": ["修补", "补齐", "贴补", "补丁"], "answer": 1, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。"}, {"id": "yy-18888", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "入冬以来，减税降费政策落地，基层干部让企业真切感受到红利。", "options": ["散发", "发放", "发射", "释放"], "answer": 3, "explanation": "「释放」与「红利」搭配得当。「释放红利」为惯用搭配；「发放」多与物资、贷款搭配；「散发」多与气味搭配；「发射」用于子弹、卫星。故选D。"}, {"id": "yy-18889", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "眼下，卡脖子技术亟待攻坚，医护人员集中力量______一个个瓶颈。", "options": ["冲破", "突破", "撞破", "捅破"], "answer": 1, "explanation": "「突破」与「瓶颈」搭配得当。「突破瓶颈」为固定搭配；「冲破」多与封锁、束缚搭配；「撞破」「捅破」为具体动作或与窗户纸等搭配。故选B。"}, {"id": "yy-18890", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，在广袤乡野间，设计师用汗水______出乡村振兴的崭新篇章。", "options": ["誊写", "抄写", "描红", "书写"], "answer": 3, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选D。"}, {"id": "yy-18891", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，发展为了人民，医护人员把一件件民生实事办到群众心坎上，持续______福祉。", "options": ["增殖", "增添", "增加", "增进"], "answer": 3, "explanation": "「增进」与「民生」搭配得当。「增进福祉」为固定搭配，题干以民生统称；「增加」多与数量搭配；「增添」多与色彩、麻烦搭配；「增殖」为生物学用语。故选D。"}, {"id": "yy-18892", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "一段时间以来，让公共服务覆盖城乡，电力工人持续______政策体系。", "options": ["补完", "完缮", "完善", "修完"], "answer": 2, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选C。"}, {"id": "yy-18893", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "开春以来，筑起生态安全屏障，志愿者们让青山常在绿水长流。", "options": ["锁牢", "筑牢", "砌牢", "拴牢"], "answer": 1, "explanation": "「筑牢」与「屏障」搭配得当。「筑牢屏障」为惯用搭配；「砌牢」用于砖石；「锁牢」「拴牢」用于器物。故选B。"}, {"id": "yy-18894", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "近年来，改革红利持续显现，市场活力不断，社区工作者信心更足。", "options": ["突发", "爆发", "迸发", "暴发"], "answer": 2, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选C。"}, {"id": "yy-18895", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "今年以来，数据孤岛必须连起来，乡村医生下决心______部门间的壁垒。", "options": ["打破", "击碎", "打碎", "砸破"], "answer": 0, "explanation": "「打破」与「壁垒」搭配得当。「打破壁垒」为固定搭配；「打碎」「砸破」「击碎」均为具体物理动作。故选A。"}, {"id": "yy-18896", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "开春以来，脱贫不是终点，税务干部多措并举______脱贫成果。", "options": ["稳固", "凝固", "加固", "巩固"], "answer": 3, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选D。"}, {"id": "yy-18897", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "入冬以来，众人的事情由众人商量，电力工人把各方______到规划图上。", "options": ["聚拢", "归拢", "凝聚", "收拢"], "answer": 2, "explanation": "「凝聚」与「智慧」搭配得当。「凝聚智慧」为惯用搭配；「聚拢」「收拢」「归拢」均为具体收拢动作，用于抽象智慧不当。故选C。"}, {"id": "yy-18898", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近年来，政府、市场、社会同向发力，工程师让各方______成强大合力。", "options": ["汇集", "聚合", "汇聚", "汇合"], "answer": 2, "explanation": "「汇聚」与「合力」搭配得当。「汇聚合力」为惯用搭配；「汇合」指水流等聚集；「汇集」指集中收集；「聚合」为化学或物理过程。故选C。"}, {"id": "yy-18899", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "近期，把资源优势变成产业优势，护林员下大气力______区域品牌。", "options": ["打制", "拍打", "锻打", "打造"], "answer": 3, "explanation": "「打造」与「品牌」搭配得当。「打造品牌」为固定搭配；「打制」「锻打」用于金属器物；「拍打」为具体动作。故选D。"}, {"id": "yy-18900", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，老厂房变身文创园，果农让工业遗存______新的活力。", "options": ["更新", "换发", "焕发", "焕新"], "answer": 2, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选C。"}, {"id": "yy-18901", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "连日来，改革红利持续显现，市场活力不断，铁路养护工信心更足。", "options": ["迸发", "爆发", "突发", "暴发"], "answer": 0, "explanation": "「迸发」与「活力」搭配得当。「迸发活力」为惯用搭配；「爆发」多用于战争、疫情或力量；「突发」多与事件搭配；「暴发」多用于疫情或含贬义。故选A。"}, {"id": "yy-18902", "module": "yanyu", "diff": 3, "exam": "事业编", "prompt": "连日来，金融活水精准滴灌，网格员为小微企业______发展动力。", "options": ["注入", "灌输", "灌入", "输入"], "answer": 0, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选A。"}, {"id": "yy-18903", "module": "yanyu", "diff": 2, "exam": "事业编", "prompt": "岁末年初，脱贫不是终点，图书管理员多措并举______脱贫成果。", "options": ["加固", "巩固", "稳固", "凝固"], "answer": 1, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选B。"}, {"id": "yy-18904", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "这些年，二十年只做一件事，税务干部在细分领域里做到极致。", "options": ["深掘", "深钻", "深挖", "深耕"], "answer": 3, "explanation": "「深耕」与「领域」搭配得当。「深耕领域」为惯用比喻搭配；「深挖」多与线索搭配；「深钻」「深掘」非规范。故选D。"}, {"id": "yy-18905", "module": "yanyu", "diff": 1, "exam": "事业编", "prompt": "近年来，脱贫不是终点，社区规划师多措并举______脱贫成果。", "options": ["加固", "稳固", "凝固", "巩固"], "answer": 3, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选D。"}, {"id": "yy-18906", "module": "yanyu", "diff": 2, "exam": "医疗编", "prompt": "眼下，每个孩子都有闪光点，公交司机善于______学生潜能。", "options": ["掘取", "开采", "挖出", "挖掘"], "answer": 3, "explanation": "「挖掘」与「潜能」搭配得当。「挖掘潜能」为固定搭配；「挖出」「掘取」为具体动作；「开采」用于矿产。故选D。"}, {"id": "yy-18907", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "开春以来，急难险重任务面前，广大建设者主动______最重的责任。", "options": ["抬起", "挑起", "扛起", "背起"], "answer": 2, "explanation": "「扛起」与「责任」搭配得当。「扛起责任」为惯用搭配；「背起」多与行囊、伤员搭配；「挑起」多与担子、重担搭配；「抬起」为具体动作。故选C。"}, {"id": "yy-18908", "module": "yanyu", "diff": 2, "exam": "省考", "prompt": "这些年，老厂房变身文创园，电力工人让工业遗存______新的活力。", "options": ["更新", "换发", "焕发", "焕新"], "answer": 2, "explanation": "「焕发」与「活力」搭配得当。「焕发活力」为固定搭配；「换发」为误写；「焕新」「更新」多用于设施、面貌且为动词直接带宾语。故选C。"}, {"id": "yy-18909", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "连日来，在广袤乡野间，公交司机用汗水______出乡村振兴的崭新篇章。", "options": ["誊写", "抄写", "书写", "描红"], "answer": 2, "explanation": "「书写」与「篇章」搭配得当。「书写篇章」为惯用搭配；「抄写」「誊写」「描红」均为照原样复写的具体动作，缺乏开创义。故选C。"}, {"id": "yy-18910", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "眼下，让公共服务覆盖城乡，护林员持续______政策体系。", "options": ["补完", "完善", "完缮", "修完"], "answer": 1, "explanation": "「完善」与「体系」搭配得当。「完善体系」为固定搭配；「完缮」「修完」「补完」均非规范搭配。故选B。"}, {"id": "yy-18911", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "盛夏时节，传统村落保护性开发，渔民既富了口袋，也______了乡愁。", "options": ["扣留", "拘留", "留住", "截留"], "answer": 2, "explanation": "「留住」与「乡愁」搭配得当。「留住乡愁」为惯用表达；「扣留」「拘留」「截留」均为法律或强制扣押义，感情色彩不合。故选C。"}, {"id": "yy-18912", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "一段时间以来，越是爬坡过坎，越要______必胜信心，非遗传承人一步一个脚印向前走。", "options": ["坚决", "坚持不懈", "坚强", "坚定"], "answer": 3, "explanation": "「坚定」与「信心」搭配得当。「坚定信心」为固定搭配；「坚决」为副词性形容词多修饰动作；「坚强」多与性格、领导搭配；「坚持不懈」为成语作状语。故选D。"}, {"id": "yy-18913", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "近期，初心如磐，使命在肩，图书管理员把承诺落到一件件小事上。", "options": ["践行", "旅行", "执行", "履行"], "answer": 0, "explanation": "「践行」与「使命」搭配得当。「践行使命」为固定搭配；「履行」多与职责、义务、合同搭配；「执行」多与命令、判决、任务搭配；「旅行」为出行义。故选A。"}, {"id": "yy-18914", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "今年以来，脱贫不是终点，非遗传承人多措并举______脱贫成果。", "options": ["巩固", "加固", "凝固", "稳固"], "answer": 0, "explanation": "「巩固」与「成果」搭配得当。「巩固成果」为固定搭配；「稳固」为形容词或使稳固；「加固」用于建筑堤坝；「凝固」为物理变化。故选A。"}, {"id": "yy-18915", "module": "yanyu", "diff": 2, "exam": "国考", "prompt": "初秋时节，民生领域还有欠账，科研人员列出清单逐项______短板。", "options": ["贴补", "补齐", "补丁", "修补"], "answer": 1, "explanation": "「补齐」与「短板」搭配得当。「补齐短板」为固定搭配；「补丁」为名词；「修补」多用于衣物器物；「贴补」多与费用搭配。故选B。"}, {"id": "yy-18916", "module": "yanyu", "diff": 3, "exam": "省考", "prompt": "近年来，放宽准入激发创业热情，消防员让创造活力。", "options": ["淌出", "涌流", "流出", "涌出"], "answer": 1, "explanation": "「涌流」与「活力」搭配得当。「活力涌流」为惯用表达；「流出」「淌出」「涌出」均用于液体且为具体动作。故选B。"}, {"id": "yy-18917", "module": "yanyu", "diff": 1, "exam": "省考", "prompt": "近期，金融活水精准滴灌，社区工作者为小微企业______发展动力。", "options": ["灌输", "灌入", "注入", "输入"], "answer": 2, "explanation": "「注入」与「动力」搭配得当。「注入动力」为惯用搭配；「灌入」用于液体；「输入」用于数据、血液；「注入」亦可用于资金，但「注入动力」最规范。故选C。"}, {"id": "yy-18918", "module": "yanyu", "diff": 3, "exam": "医疗编", "prompt": "初秋时节，乡情是最深的牵挂，青年学子以商会为平台______情感纽带。", "options": ["绑牢", "系牢", "捆牢", "织牢"], "answer": 3, "explanation": "「织牢」与「纽带」搭配得当。「织牢纽带」为惯用比喻搭配；「系牢」「捆牢」「绑牢」均为具体系绑动作。故选D。"}, {"id": "yy-18919", "module": "yanyu", "diff": 1, "exam": "国考", "prompt": "岁末年初，老旧小区加装电梯、增设车位，市场监管部门尽力______居民多样需求。", "options": ["满足", "充盈", "充足", "满意"], "answer": 0, "explanation": "「满足」与「需求」搭配得当。「满足需求」为固定搭配；「满意」为形容词；「充足」「充盈」为形容词不能带宾语。故选A。"}, {"id": "yy-18920", "module": "yanyu", "diff": 2, "exam": "教师编", "prompt": "一段时间以来，小哨兵大作用，市场监管部门让基层网格______更大作用。", "options": ["发挥", "施展", "发扬", "表现"], "answer": 0, "explanation": "「发挥」与「作用」搭配得当。「发挥作用」为固定搭配；「发扬」多与传统搭配；「施展」多与才华、拳脚搭配。故选A。"}]);